	'Educandos de %d años o más' => '%d urte edo gehiagoko hezigaiak',
	'El código de la organización tiene que ser un número de 1 a 3 cifras que no empiece por 0.' => 'Erakundearen kodeak 1etik 3ra bitarteko zifrako zenbaki bat izan behar du, 0z hasten ez dena.',
	'El grupo %s ya está dado de alta.' => '%s taldea alta emanda dago jada.',
	'El nº de grupo debe tener hasta 3 cifras (p. ej. 684).' => 'Taldearen zenbakiak gehienez 3 zifra izan behar ditu (adib. 684).',
	'Elige la organización federada de la lista.' => 'Aukeratu zerrendako erakunde federatua.',
