	// Domiciliaciones SEPA
	'Como parte de sus derechos, el deudor está legitimado al reembolso por su entidad en los términos y condiciones del contrato suscrito con la misma. La solicitud de reembolso deberá efectuarse dentro de las ocho semanas que siguen a la fecha de adeudo en cuenta. Puede obtener información adicional sobre sus derechos en su entidad financiera.' => 'Bere eskubideen barruan, zordunak bere erakundeak itzultzea eskatzeko legitimazioa du, erakunde horrekin sinatutako kontratuaren baldintzetan. Itzultzeko eskaera kontuan kargua egin zen datatik hasi eta zortzi asteko epean egin beharko da. Bere eskubideei buruzko informazio gehigarria bere finantza-erakundean lor dezake.',
	'El BIC no es válido (8 u 11 caracteres). Puedes dejarlo vacío.' => 'BIC kodea ez da baliozkoa (8 edo 11 karaktere). Hutsik utz dezakezu.',
	'El IBAN debe empezar por dos letras del país y dos cifras de control (por ejemplo ES91…).' => 'IBANak herrialdeko bi letrarekin eta kontrolerako bi zifrarekin hasi behar du (adibidez ES91…).',
	'El IBAN no es de un país de la zona SEPA.' => 'IBANa ez da SEPA eremuko herrialde batekoa.',
	'El deudor puede anular esta autorización cuando quiera desde «Mis pagos» o avisando a la Tesorería del grupo.' => 'Zordunak nahi duenean ezeztatu dezake baimen hau «Nire ordainketak» atalean edo taldeko Diruzaintzari abisatuz.',
	'El identificador del acreedor no tiene el formato correcto (en España, ES + 2 cifras de control + 3 caracteres + NIF: 16 caracteres, p. ej. ES12ZZZG12345678).' => 'Hartzekodunaren identifikatzaileak ez du formatu zuzena (Espainian, ES + 2 kontrol-zifra + 3 karaktere + IFZ: 16 karaktere, adib. ES12ZZZG12345678).',
	'El servidor de correo no ha aceptado el email.' => 'Posta-zerbitzariak ez du emaila onartu.',
	'Elige la fecha de cobro.' => 'Aukeratu kobrantza-data.',
	'Enviada al banco' => 'Bankura bidalia',
	'Error desconocido' => 'Errore ezezaguna',
	'Escribe el IBAN.' => 'Idatzi IBANa.',
	'Escribe el nombre y los apellidos del titular de la cuenta.' => 'Idatzi kontuaren titularraren izen-abizenak.',
	'Escribe la dirección del titular (calle, código postal y población).' => 'Idatzi titularraren helbidea (kalea, posta-kodea eta herria).',
	'Esta autorización sirve para cobrar la cuota y otros pagos del grupo (por ejemplo, las cuotas de cada ronda). Tipo de pago: recurrente. %s comunicará al deudor la fecha y el importe de cada adeudo con al menos %d días de antelación (por email y en «Mis pagos»).' => 'Baimen honek taldearen kuota eta bestelako ordainketak kobratzeko balio du (adibidez, txanda bakoitzeko kuotak). Ordainketa mota: errepikakorra. %s(e)k zordunari kargu bakoitzaren data eta zenbatekoa jakinaraziko dizkio gutxienez %d egun lehenago (emailez eta «Nire ordainketak» atalean).',
	'Falta el identificador del acreedor (ICS). Lo da el banco al contratar las domiciliaciones.' => 'Hartzekodunaren identifikatzailea (ICS) falta da. Bankuak ematen du helbideratzeak kontratatzean.',
	'Falta el nombre del acreedor (el del grupo o la asociación que cobra).' => 'Hartzekodunaren izena falta da (kobratzen duen taldearena edo elkartearena).',
	'Faltan datos del acreedor: complétalos en «Datos del acreedor».' => 'Hartzekodunaren datuak falta dira: bete itzazu «Hartzekodunaren datuak» atalean.',
	'Familia %s: %s' => '%s familia: %s',
	'Familia %s: el IBAN de la autorización no es válido (o ya no se conserva).' => '%s familia: baimenaren IBANa ez da baliozkoa (edo ez da jada gordetzen).',
	'Familia %s: el importe debe ser mayor que 0.' => '%s familia: zenbatekoak 0 baino handiagoa izan behar du.',
	'Familia %s: falta el nombre del titular.' => '%s familia: titularraren izena falta da.',
	'Familia %s: tipo de secuencia no válido.' => '%s familia: sekuentzia mota baliogabea.',
	'Generada' => 'Sortua',
	'Hemos guardado tu autorización de domiciliación SEPA' => 'Zure SEPA helbideratze-baimena gorde dugu',
	'IBAN del acreedor: ' => 'Hartzekodunaren IBANa: ',
	'La autorización tiene que firmarla tu madre, padre o tutor/a desde su cuenta: por ser menor de edad no puedes firmarla tú.' => 'Baimena zure amak, aitak edo tutoreak sinatu behar du bere kontutik: adingabea zarenez, ezin duzu zuk sinatu.',
	'La cuenta no tiene un email al que escribir.' => 'Kontuak ez du emailik idazteko.',
	'La fecha de cobro no es válida.' => 'Kobrantza-data ez da baliozkoa.',
	'La fecha de cobro tiene que ser un día laborable (de lunes a viernes).' => 'Kobrantza-data lanegun bat izan behar da (astelehenetik ostiralera).',
	'La fecha de cobro tiene que ser, como pronto, el %s (%d días hábiles desde hoy): los bancos necesitan ese margen.' => 'Kobrantza-data %s baino lehenago ezin da izan (gaurtik %d lanegun): bankuek tarte hori behar dute.',
	'La fecha del cobro no es válida (no puede ser posterior a hoy).' => 'Kobrantzaren data ez da baliozkoa (ezin da gaurkoa baino geroagokoa izan).',
	'Los cobros solo se registran de una remesa enviada al banco.' => 'Kobrantzak banku bati bidalitako remesa batean soilik erregistratzen dira.',
	'Los datos de esta remesa ya no se conservan.' => 'Remesa honen datuak ez dira jada gordetzen.',
	'Los dígitos de control del IBAN no cuadran: revisa que esté bien escrito.' => 'IBANaren kontrol-digituak ez datoz bat: egiaztatu ondo idatzita dagoela.',
	'Mediante la firma de esta orden de domiciliación, el deudor autoriza (A) a %s a enviar instrucciones a la entidad del deudor para adeudar su cuenta y (B) a la entidad para efectuar los adeudos en su cuenta siguiendo las instrucciones de %s.' => 'Helbideratze-agindu hau sinatuz, zordunak (A) %s(r)i baimena ematen dio zordunaren erakundeari jarraibideak bidaltzeko bere kontuan kargua egiteko eta (B) erakundeari bere kontuan kargu horiek egiteko, %s(r)en jarraibideei jarraituz.',
	'No hay ningún adeudo que incluir.' => 'Ez dago barne hartzeko kargurik.',
	'No se ha podido guardar la autorización. Inténtalo de nuevo.' => 'Ezin izan da baimena gorde. Saiatu berriro.',
	'No se ha podido guardar la remesa. Inténtalo de nuevo.' => 'Ezin izan da remesa gorde. Saiatu berriro.',
	'No se puede leer la autorización (pídele que la firme de nuevo)' => 'Ezin da baimena irakurri (eskatu berriro sinatzeko)',
	'Sin autorización SEPA' => 'SEPA baimenik gabe',
	'Todas esas familias ya están en otra remesa que aún no tiene registrados sus cobros.' => 'Familia horiek guztiak oraindik kobrantzarik erregistratu gabe duen beste remesa batean daude jada.',
	'Todo lo pendiente' => 'Zain dagoen guztia',
	'Tu cuenta no puede firmar autorizaciones de domiciliación.' => 'Zure kontuak ezin ditu helbideratze-baimenak sinatu.',
	'Un IBAN de %s tiene %d caracteres y este tiene %d.' => '%s(e)ko IBAN batek %d karaktere ditu eta honek %d ditu.',
	'Ya está en la remesa %s (falta registrar su cobro)' => 'Dagoeneko %s remesan dago (kobrantza erregistratzea falta da)',
	'[%s] Aviso de cargo el %s' => '[%s] Kargu-oharra: %s',

	// Emails
	'%1$s te ha dado acceso al área privada del %2$s como <strong>%3$s</strong>.' => '%1$s(e)k %2$s(r)en eremu pribaturako sarbidea eman dizu <strong>%3$s</strong> gisa.',
	'%1$s te ha dado acceso al área privada del %2$s.' => '%1$s(e)k %2$s(r)en eremu pribaturako sarbidea eman dizu.',
	'Cuenta: <strong>%s</strong>' => 'Kontua: <strong>%s</strong>',
	'Desde ahora la cuenta <strong>%s</strong> entra con esta dirección de email (o con ese usuario).' => 'Hemendik aurrera <strong>%s</strong> kontua email-helbide honekin (edo erabiltzaile horrekin) sartzen da.',
	'Domiciliación SEPA' => 'SEPA helbideratzea',
	'El enlace es personal, de un solo uso y caduca en %d días.' => 'Esteka pertsonala da, erabilera bakarrekoa eta %d egunetan iraungitzen da.',
	'El enlace es personal, de un solo uso y caduca en 24 horas.' => 'Esteka pertsonala da, erabilera bakarrekoa eta 24 ordutan iraungitzen da.',
	'Elegir contraseña nueva' => 'Aukeratu pasahitz berri bat',
	'Es un adeudo directo SEPA, con la autorización que firmaste (referencia %s). Puedes ver el cargo y tus pagos en «Mis pagos». Si no estás de acuerdo, avísanos antes de esa fecha.' => 'SEPA zuzeneko kargua da, sinatu zenuen baimenarekin (erreferentzia: %s). Kargua eta zure ordainketak «Nire ordainketak» atalean ikus ditzakezu. Ados ez bazaude, jakinarazi iezaguzu data hori baino lehen.',
	'Escribe a %s, con el nombre del socio/a y tu relación con él o ella (madre, padre, tutor/a o el propio socio/a).' => 'Idatzi %s(r)i, bazkidearen izenarekin eta berarekin duzun harremanarekin (ama, aita, tutorea edo bazkide bera).',
	'Habla con la Secretaría de tu grupo, diciéndole el nombre del socio/a y tu relación con él o ella (madre, padre, tutor/a o el propio socio/a).' => 'Hitz egin zure taldeko Idazkaritzarekin, bazkidearen izena eta berarekin duzun harremana esanez (ama, aita, tutorea edo bazkide bera).',
	'Hemos comprobado tu solicitud de acceso y ya está aprobada. Desde el área privada podrás consultar y mantener al día tus datos y los de tu familia.' => 'Zure sarbide-eskaera egiaztatu dugu eta onartuta dago. Eremu pribatutik zure datuak eta zure familiarenak kontsultatu eta eguneratuta mantendu ahalko dituzu.',
	'Hemos comprobado tu solicitud de acceso y ya está aprobada. Desde el área privada podrás consultar y mantener al día tus datos.' => 'Zure sarbide-eskaera egiaztatu dugu eta onartuta dago. Eremu pribatutik zure datuak kontsultatu eta eguneratuta mantendu ahalko dituzu.',
	'Hemos guardado tu <strong>autorización de domiciliación SEPA</strong> para los pagos del %s.' => '%s(r)en ordainketetarako zure <strong>SEPA helbideratze-baimena</strong> gorde dugu.',
	'Hemos recibido una petición para elegir una contraseña nueva para el usuario <strong>%s</strong> (con el que también puedes entrar usando esta dirección de email).' => '<strong>%s</strong> erabiltzailearentzat pasahitz berri bat aukeratzeko eskaera jaso dugu (email-helbide hau erabiliz ere sartu zaitezke).',
	'Hemos revisado tu solicitud de acceso al área privada del <strong>%s</strong> y, con los datos que nos has enviado, <strong>no hemos podido darte acceso</strong>.' => '<strong>%s</strong>(r)en eremu pribaturako zure sarbide-eskaera berrikusi dugu eta, bidali dizkiguzun datuekin, <strong>ezin izan dizugu sarbiderik eman</strong>.',
	'Hola, %s:' => 'Kaixo, %s:',
	'Hola:' => 'Kaixo:',
	'Ir a Mis pagos' => 'Joan Nire ordainketak atalera',
	'Para activar tu cuenta y elegir tu contraseña, pulsa el botón:' => 'Zure kontua aktibatzeko eta pasahitza aukeratzeko, sakatu botoia:',
	'Pulsa el botón para elegir tu contraseña:' => 'Sakatu botoia zure pasahitza aukeratzeko:',
	'Pulsa el botón para elegirla:' => 'Sakatu botoia aukeratzeko:',
	'Referencia de la autorización: <strong>%s</strong>' => 'Baimenaren erreferentzia: <strong>%s</strong>',
	'Se te ha dado acceso al área privada del %1$s como <strong>%2$s</strong>.' => '%1$s(r)en eremu pribaturako sarbidea eman dizute <strong>%2$s</strong> gisa.',
	'Se te ha dado acceso al área privada del %s.' => '%s(r)en eremu pribaturako sarbidea eman dizute.',
	'Si el botón no funciona, copia esta dirección en tu navegador:' => 'Botoiak funtzionatzen ez badu, kopiatu helbide hau zure nabigatzailean:',
	'Si no esperabas este correo, puedes ignorarlo.' => 'Posta hau espero ez baduzu, ez ikusiarena egin dezakezu.',
	'Si no has pedido tú este acceso, puedes ignorar este correo.' => 'Sarbide hau zuk eskatu ez baduzu, ez ikusiarena egin diezaiokezu posta honi.',
	'Suele ser porque algún dato no coincide con la ficha del socio/a o porque la ficha no está al día. Si crees que es un error, o quieres volver a intentarlo, ponte en contacto con nosotros:' => 'Normalean datuen bat ez datorrelako bazkidearen fitxarekin edo fitxa eguneratuta ez dagoelako izaten da. Akatsa dela uste baduzu, edo berriro saiatu nahi baduzu, jarri gurekin harremanetan:',
	'También puedes entrar escribiendo esta dirección de email en lugar del usuario.' => 'Erabiltzailearen ordez email-helbide hau idatzita ere sar zaitezke.',
	'Te avisamos de que <strong>%1$s</strong> se cargarán <strong>%2$s</strong> en la cuenta <strong>%3$s</strong>, en concepto de «%4$s».' => 'Jakinarazten dizugu <strong>%1$s</strong> kobratuko direla <strong>%2$s</strong> egunean <strong>%3$s</strong> kontuan, «%4$s» kontzeptuan.',
	'Te avisaremos antes de cada cargo, con su fecha y su importe. Puedes ver la autorización, imprimirla o anularla cuando quieras desde «Mis pagos».' => 'Kargu bakoitzaren aurretik abisatuko dizugu, bere data eta zenbatekoarekin. Baimena ikusi, inprimatu edo ezeztatu dezakezu nahi duzunean «Nire ordainketak» atalean.',
	'Tu usuario para entrar es:' => 'Sartzeko zure erabiltzailea:',
	'Tutor / Padre / Madre' => 'Tutorea / Aita / Ama',
	'¡Te damos la bienvenida al área privada del %s!' => 'Ongi etorri %s(r)en eremu pribatura!',
	'¿Dudas? Escribe a %s.' => 'Zalantzarik? Idatzi %s(r)i.',
	'¿Dudas? Habla con la Tesorería de tu grupo.' => 'Zalantzarik? Hitz egin zure taldeko Diruzaintzarekin.',

