	'Ahora en el CRM' => 'Orain CRMan',
	'Al aprobar un cambio se guarda en el CRM. Si el dato del CRM ha cambiado desde que se propuso, se avisa antes de sobrescribirlo. Nadie puede aprobar sus propias propuestas.' => 'Aldaketa bat onartzean CRMan gordetzen da. Proposatu zenetik CRMko datua aldatu bada, gainidatzi aurretik abisatzen da. Inork ezin ditu bere proposamenak onartu.',
