	'Autorizaciones y formación' => 'Baimenak eta prestakuntza',
	'Cambio pendiente de aprobación: «' => 'Onarpenaren zain dagoen aldaketa: «',
	'Cambios propuestos en esta ficha' => 'Fitxa honetan proposatutako aldaketak',
