	'El CRM no ha aceptado el valor.' => 'CRMak ez du balioa onartu.',
	'El dato del CRM ha cambiado desde que se propuso. Revísalo y confirma si quieres aplicarlo igualmente.' => 'CRMko datua proposatu zenetik aldatu da. Berrikusi eta berretsi hala ere aplikatu nahi duzun.',
	'El usuario del CRM de tu grupo no tiene permiso para editar fichas: todos los datos son de' => 'Zure taldeko CRMko erabiltzaileak ez du fitxak editatzeko baimenik: datu guztiak hauek dira:',
	'El usuario del CRM del grupo no puede editar fichas ahora mismo: los cambios no se pueden aprobar hasta que lo tenga.' => 'Taldeko CRMko erabiltzaileak ezin ditu fitxak editatu une honetan: aldaketak ezin dira onartu hori egin dezakeen arte.',
	'El usuario del CRM del grupo no tiene permiso para editar fichas.' => 'Taldeko CRMko erabiltzaileak ez du fitxak editatzeko baimenik.',
	'Elimina por completo cualquier producto de origen animal, incluyendo la miel, los lácteos y los huevos.' => 'Animalia-jatorriko edozein produktu erabat kentzen du, eztia, esnekiak eta arrautzak barne.',
	'Enviar cambios para su aprobación' => 'Bidali aldaketak onar daitezen',
	'Ese cambio no se puede cancelar.' => 'Aldaketa hau ezin da ezeztatu.',
	'Ese cambio ya no está pendiente.' => 'Aldaketa hau ez dago jada zain.',
	'Este campo no se puede editar desde la web.' => 'Eremu hau ezin da webetik editatu.',
	'Excluye la carne y el pescado, pero puede permitir derivados como huevos y lácteos (ovolactovegetariana).' => 'Haragia eta arraina kentzen ditu, baina eratorriak onar ditzake, hala nola arrautzak eta esnekiak (ovolaktobegetarianoa).',
	'Expandir todo' => 'Zabaldu guztia',
	'Familia / tutores' => 'Familia / tutoreak',
	'Fecha' => 'Data',
	'Guardar cambios en el CRM' => 'Gorde aldaketak CRMan',
	'Incluye alimentos de origen animal y vegetal sin mayores restricciones.' => 'Animalia- eta landare-jatorriko elikagaiak ditu, murrizketa handirik gabe.',
	'Indica el motivo del rechazo: se le mostrará a quien lo propuso.' => 'Adierazi ukatzearen arrazoia: proposatu duenari erakutsiko zaio.',
	'Lo asigna Scouts de España.' => 'Scouts de Españak ematen du.',
	'Los cambios que hagas los revisará la Secretaría o un scouter de su sección antes de guardarse en el CRM.' => 'Egiten dituzun aldaketak Idazkaritzak edo bere atalaren scouter batek berrikusiko ditu CRMan gorde aurretik.',
	'Los cambios se guardan directamente en el CRM. 🔒 = solo lectura (pasa el ratón por encima para ver el motivo).' => 'Aldaketak zuzenean CRMan gordetzen dira. 🔒 = irakurtzeko soilik (pasatu sagua gainetik arrazoia ikusteko).',
	'Menores a tu cargo' => 'Zure kargura dauden adingabeak',
	'Motivo del rechazo' => 'Ukatzearen arrazoia',
