	'Descendente' => 'Beheranzkoa',
	'En cada número repetido lo conservará quien entra en la web con él (o quien tiene membresía activa, o el nº de Scouts de España más antiguo); el resto recibirá el siguiente número libre, guardado en el CRM. Se hace en segundo plano. ¿Continuar?' => 'Errepikatutako zenbaki bakoitzean, webean zenbaki horrekin sartzen denak (edo kidetza aktiboa duenak, edo Scouts de Españako zenbaki zaharrenak) mantenduko du; gainerakoek hurrengo zenbaki librea jasoko dute, CRMan gordeta. Atzeko planoan egiten da. Jarraitu nahi duzu?',
	'En el CRM pasará de «%s» a «%s». ¿Continuar?' => 'CRMan «%s» izatetik «%s» izatera pasako da. Jarraitu nahi duzu?',
	'Estos números se asignaron desde la web y aún no están en el CRM. Pásalos con el botón de arriba o desde cada ficha.' => 'Zenbaki hauek webetik esleitu ziren eta oraindik ez daude CRMan. Pasatu goiko botoiarekin edo fitxa bakoitzetik.',
	'Estos números se han asignado desde la web. Anótalos en el CRM (campo «Nº de socio/a local/territorial»); al detectarlos en el CRM desaparecerán de esta lista.' => 'Zenbaki hauek webetik esleitu dira. Idatzi CRMan («Bazkide-zenbaki lokala/lurraldekoa» eremuan); CRMan detektatzen direnean zerrenda honetatik desagertuko dira.',
	'Filtrar' => 'Iragazi',
