	'Las fichas se leen del CRM cada pocos minutos para que las páginas vayan rápido (la última lectura fue' => 'Fitxak CRMtik irakurtzen dira minutu batzuetan behin, orriak azkar joan daitezen (azken irakurketa hau izan zen:',
