	'Para corregirlos desde aquí, el usuario del CRM del grupo necesita permiso para editar fichas. Mientras tanto, corrígelos en el CRM (campo «Nº de socio/a local/territorial»).' => 'Hemendik zuzentzeko, taldeko CRMko erabiltzaileak fitxak editatzeko baimena behar du. Bitartean, zuzendu CRMan («Bazkide-zenbaki lokala/lurraldekoa» eremuan).',
