	'Se guardará el nº %s en la ficha del CRM de %s. ¿Continuar?' => '%s zenbakia %s(r)en CRMko fitxan gordeko da. Jarraitu nahi duzu?',
	'Se guardará en el CRM el formato correcto (7 + grupo + 4 cifras) de todos los números con formato antiguo (también los de fichas sin membresía activa). Se hace en segundo plano: podrás seguir usando la web. ¿Continuar?' => 'Formatu zaharra duten zenbaki guztien formatu zuzena (7 + taldea + 4 zifra) CRMan gordeko da (kidetza aktiborik gabeko fitxenak ere bai). Atzeko planoan egiten da: webak erabiltzen jarrai dezakezu. Jarraitu nahi duzu?',
	'Se guardarán en el CRM los números generados desde la web. Se hace en segundo plano. ¿Continuar?' => 'Webetik sortutako zenbakiak CRMan gordeko dira. Atzeko planoan egiten da. Jarraitu nahi duzu?',
	'Se pueden corregir una a una desde la lista, o volver a lanzar la corrección cuando se haya resuelto el motivo.' => 'Banan-banan zuzen daitezke zerrendatik, edo zuzenketa berriro abiarazi daiteke arrazoia konpondu denean.',
