	'. Es el que ve quien no puede comprobar sus datos y el que lleva el aviso de una solicitud rechazada. Un administrador lo pone en wp-admin → Grupos Scouts → (el grupo) → «Email de contacto del grupo».' => '. Bere datuak egiaztatu ezin dituenak ikusten duena da, eta baita ukatutako eskaera baten oharrak daramana ere. Administratzaile batek wp-admin → Grupos Scouts → (taldea) → «Email de contacto del grupo» atalean jartzen du.',
