	'Se creará su cuenta de participante (su nº de socio/a) y le llegará la invitación con la bienvenida.' => 'Bere partaide-kontua sortuko da (bere bazkide-zenbakia) eta gonbidapena iritsiko zaio ongi etorriarekin.',
