	'los emails no salen a internet (así no llegan a familias reales). Se recogen en Mailpit:' => 'emailak ez dira internetera ateratzen (horrela ez zaizkie benetako familiei iristen). Mailpit-en biltzen dira:',
	'porque no había dirección de destino en el CRM.' => 'CRMan helmuga-helbiderik ez zegoelako.',
