	'(vacía)' => '(hutsik)',
	'(ábrelo con Excel o LibreOffice, sustituye las filas de ejemplo por tu material y guárdalo como CSV)' => '(ireki Excel edo LibreOffice-rekin, ordeztu adibideko errenkadak zure materialarekin eta gorde CSV gisa)',
	'Cocina' => 'Sukaldea',
	'Corrígelas y vuelve a importar solo esas filas (las demás ya están en el inventario). Puedes descargarlas en un CSV con el motivo de cada una.' => 'Zuzendu eta inportatu berriro errenkada horiek bakarrik (besteak inbentarioan daude jada). CSV batean deskarga ditzakezu, bakoitzaren arrazoiarekin.',
	'Crear los tipos de material que todavía no existan (si no, esas filas no se importan)' => 'Sortu oraindik ez dauden material-motak (bestela, errenkada horiek ez dira inportatzen)',
	'Cuerda de 20 m' => '20 m-ko soka',
	'Cómo tiene que ser el fichero' => 'Nolakoa izan behar duen fitxategiak',
	'Descargar las filas con error (CSV)' => 'Deskargatu errorea duten errenkadak (CSV)',
	'Descargar un fichero de ejemplo' => 'Deskargatu adibide-fitxategi bat',
	'El fichero es demasiado grande (como mucho %d MB).' => 'Fitxategia handiegia da (gehienez %d MB).',
	'El fichero está vacío o no se ha podido leer.' => 'Fitxategia hutsik dago edo ezin izan da irakurri.',
	'El fichero no es un CSV (parece una hoja de Excel u otro formato). Guárdalo como «CSV (delimitado por punto y coma)» y vuelve a intentarlo.' => 'Fitxategia ez da CSV bat (Excel orri bat edo beste formatu bat dirudi). Gorde «CSV (puntu eta komaz mugatua)» gisa eta saiatu berriro.',
	'El fichero no se ha podido subir. Tiene que ser un CSV de hasta %d MB.' => 'Ezin izan da fitxategia igo. Gehienez %d MB-ko CSV bat izan behar du.',
	'El fichero solo tiene la cabecera: no hay ningún material que importar.' => 'Fitxategiak goiburua baino ez du: ez dago inportatzeko materialik.',
	'El fichero tiene demasiadas filas (como mucho %d). Pártelo en varios.' => 'Fitxategiak errenkada gehiegi ditu (gehienez %d). Zatitu hainbat fitxategitan.',
	'El fichero tiene que ser un CSV (.csv). Desde Excel: «Guardar como» → «CSV (delimitado por punto y coma)».' => 'Fitxategiak CSV bat (.csv) izan behar du. Exceletik: «Gorde honela» → «CSV (puntu eta komaz mugatua)».',
	'El informe de esa importación ya no está disponible (se guarda una hora).' => 'Inportazio horren txostena jada ez dago eskuragarri (ordubetez gordetzen da).',
	'El nº de serie «%1$s» ya está en la fila %2$d del fichero.' => '«%1$s» serie-zenbakia fitxategiaren %2$d. errenkadan dago jada.',
	'El precio, con coma o punto para los decimales (12,50). El año de compra, con cuatro cifras o en blanco.' => 'Prezioa, hamartarretarako koma edo puntuarekin (12,50). Erosketa-urtea, lau zifrarekin edo hutsik.',
	'El tipo «%s» no existe.' => '«%s» mota ez dago.',
	'Elige el fichero CSV que quieres importar.' => 'Aukeratu inportatu nahi duzun CSV fitxategia.',
