	'La primera fila, los nombres de las columnas: %s. En cualquier orden; las que no uses se pueden quitar.' => 'Lehen errenkadan, zutabeen izenak: %s. Edozein ordenatan; erabiltzen ez dituzunak ken daitezke.',
	'Motivo del error' => 'Errorearen arrazoia',
	'No se ha importado nada.' => 'Ez da ezer inportatu.',
	'Obligatorias: %s. La cantidad, un número entero de 0 en adelante.' => 'Derrigorrezkoak: %s. Kopurua, 0tik gorako zenbaki osoa.',
