	'Guardar y enviar a Tesorería' => 'Gorde eta bidali Diruzaintzara',
	'Indica cuántas unidades hay que comprar de cada material (0 para quitarlo) y su precio estimado. Al guardarla se envía a Tesorería para que le dé el visto bueno; sin él no se puede imprimir.' => 'Adierazi material bakoitzetik zenbat unitate erosi behar diren (0 kentzeko) eta haren prezio estimatua. Gordetzean Diruzaintzara bidaltzen da oniritzia eman dezan; hura gabe ezin da inprimatu.',
