	'Lista %s cancelada.' => '%s zerrenda ezeztatu da.',
	'Lista %s con el visto bueno de Tesorería. Ya se puede imprimir.' => '%s zerrendak Diruzaintzaren oniritzia du. Jada inprima daiteke.',
	'Lista %s creada, pero no se ha podido avisar a Tesorería por email: díselo para que le dé el visto bueno.' => '%s zerrenda sortu da, baina ezin izan zaio Diruzaintzari emailez abisatu: esaiozu oniritzia eman diezaion.',
	'Lista %s creada. No había nadie más de Tesorería a quien avisar: puedes darle tú el visto bueno.' => '%s zerrenda sortu da. Ez zegoen Diruzaintzako beste inor abisatzeko: zuk zeuk eman diezaiokezu oniritzia.',
