	'Otros ingresos' => 'Beste diru-sarrera batzuk',
	'Para clasificar los movimientos del banco que no son cuotas de las familias. Cada tipo es de gasto, de ingreso o de las dos cosas (por ejemplo, devoluciones). Un tipo que usa algún movimiento no se puede borrar, pero sí cambiarle el nombre.' => 'Familien kuotak ez diren bankuko mugimenduak sailkatzeko. Mota bakoitza gastukoa, diru-sarrerakoa edo bietakoa da (adibidez, itzulketak). Mugimenduren batek erabiltzen duen mota ezin da ezabatu, baina izena alda dakioke.',
	'Para los movimientos que no son cuotas de las familias: gastos (material, transporte, comisiones…) o ingresos (donativos, subvenciones…). El tipo sirve para saber en qué se gasta y de dónde entra el dinero.' => 'Familien kuotak ez diren mugimenduetarako: gastuak (materiala, garraioa, komisioak…) edo diru-sarrerak (dohaintzak, diru-laguntzak…). Motak balio du jakiteko zertan gastatzen den eta nondik sartzen den dirua.',
	'Por ejemplo: factura 2026/031 de la tienda de deportes' => 'Adibidez: kirol-dendako 2026/031 faktura',
