	// Tesorería: control de pagos (v0.20)
	'Los movimientos del banco solo los usan Secretaría, Coordinación y Tesorería.' => 'Bankuko mugimenduak Idazkaritzak, Koordinazioak eta Diruzaintzak bakarrik erabiltzen dituzte.',
