	'Lleva el nombre «%s»' => '«%s» izena darama',
	'Los ingresos importados del banco que aún no están conciliados. Elige el de esta familia: el pago se registra con su fecha y su importe.' => 'Bankutik inportatutako eta oraindik bateratu gabeko diru-sarrerak. Aukeratu familia honena: ordainketa haren data eta zenbatekoarekin erregistratzen da.',
	'Ningún ingreso coincide con la búsqueda.' => 'Ez dago bilaketarekin bat datorren diru-sarrerarik.',
