	'Hay varias fichas en tu grupo con este documento: habría que unificarlas en el CRM.' => 'Zure taldean hainbat fitxak dute dokumentu hau: CRMan bateratu beharko lirateke.',
	'No hay que crear otra ficha: si vuelve al grupo, solo necesita una membresía nueva en la suya.' => 'Ez da beste fitxarik sortu behar: taldera itzultzen bada, kidetza berri bat besterik ez du behar berean.',
	'No se ha podido comprobar si está dada de alta en otros grupos u organizaciones. Puedes seguir igualmente.' => 'Ezin izan da egiaztatu beste talde edo erakunde batzuetan alta emanda dagoen. Hala ere, jarraitu dezakezu.',
	'Nº Scouts de España %s' => 'Scouts de Españako zk. %s',
	'Puede estar en varios a la vez: se puede dar de alta también en tu grupo.' => 'Hainbatetan egon daiteke aldi berean: zure taldean ere alta eman daiteke.',
	'membresía activa: %s' => 'kidetza aktiboa: %s',
