	'Ese enlace no se puede hacer desde la web.' => 'Lotura hori ezin da webetik egin.',
	'Esta ficha ya tiene un documento. Si está mal, corrígelo en el CRM.' => 'Fitxa honek badu dokumentu bat. Gaizki badago, zuzendu CRMan.',
	'Esta persona ya está dada de alta en otro grupo u organización de Scouts de España. Confirma que quieres darla de alta también en tu grupo.' => 'Pertsona honek alta emanda du dagoeneko Scouts de Españako beste talde edo erakunde batean. Berretsi zure taldean ere alta eman nahi diozula.',
	'Este documento ya está dado de alta en otro grupo u organización de Scouts de España. Confirma que es la misma persona y quieres guardarlo.' => 'Dokumentu honek alta emanda du dagoeneko Scouts de Españako beste talde edo erakunde batean. Berretsi pertsona bera dela eta gorde nahi duzula.',
	'Falta el género.' => 'Generoa falta da.',
	'Falta el nombre.' => 'Izena falta da.',
	'Falta la fecha de nacimiento.' => 'Jaiotze-data falta da.',
	'Faltan los apellidos.' => 'Abizenak falta dira.',
	'Hay otra operación a medias con esta persona. Termínala antes.' => 'Beste eragiketa bat dago erdibidean pertsona honekin. Amaitu lehenago.',
	'Hay un email que no es válido.' => 'Baliozkoa ez den posta elektroniko bat dago.',
	'La fecha de nacimiento no es válida.' => 'Jaiotze-data ez da baliozkoa.',
	'Las altas en el CRM no están activadas para tu grupo.' => 'CRMko altak ez daude aktibatuta zure taldearentzat.',
	'No se ha podido comprobar si este documento está en otros grupos u organizaciones. Confirma que quieres guardarlo.' => 'Ezin izan da egiaztatu dokumentu hau beste talde edo erakunde batzuetan dagoen. Berretsi gorde nahi duzula.',
	'No se ha podido comprobar si está dada de alta en otros grupos u organizaciones. Confirma que quieres seguir.' => 'Ezin izan da egiaztatu beste talde edo erakunde batzuetan alta emanda dagoen. Berretsi jarraitu nahi duzula.',
	'No se ha podido empezar la operación. Vuelve a intentarlo.' => 'Ezin izan da eragiketa hasi. Saiatu berriro.',
	'No se ha podido hacer: ' => 'Ezin izan da egin: ',
	'No tiene ninguna membresía activa.' => 'Ez du kidetza aktiborik.',
	'Otra ficha de tu grupo ya tiene este documento (%s): sería la misma persona dos veces. Revísalo antes de seguir.' => 'Zure taldeko beste fitxa batek badu dokumentu hau (%s): pertsona bera bi aldiz litzateke. Berrikusi jarraitu aurretik.',
	'Para cambiar de sección tiene que tener una membresía activa (y solo una).' => 'Atalez aldatzeko kidetza aktibo bat izan behar du (eta bakarra).',
	'Se ha quedado a medias. Vuelve a intentarlo: seguirá donde se quedó, sin crear otra ficha. Motivo: ' => 'Erdibidean geratu da. Saiatu berriro: utzi zuen tokitik jarraituko du, beste fitxarik sortu gabe. Arrazoia: ',
	'Ya está en esa sección.' => 'Atal horretan dago jada.',
	'Ya hay un alta en curso para esta persona. Espera a que termine.' => 'Badago alta bat martxan pertsona honentzat. Itxaron amaitu arte.',
	'Ya tiene ficha en tu grupo: no se crea otra. Si no tiene membresía activa, dale una nueva en su ficha.' => 'Badu fitxa zure taldean: ez da beste bat sortzen. Kidetza aktiborik ez badu, eman berri bat bere fitxan.',
	'Ya tiene una membresía activa. Para pasarla a otra sección, usa «Cambiar de sección».' => 'Badu kidetza aktibo bat. Beste atal batera pasatzeko, erabili «Atalez aldatu».',

	// Personas · altas en el CRM (v0.23, doc 34)
	'La fecha de alta no puede ser posterior a hoy.' => 'Alta-data ezin da gaur baino geroagokoa izan.',
	'La fecha de baja no puede ser anterior a la de alta (%s).' => 'Baja-data ezin da alta-data baino lehenagokoa izan (%s).',
	'La fecha de baja no puede ser posterior a hoy.' => 'Baja-data ezin da gaur baino geroagokoa izan.',
	'La fecha del cambio no puede ser anterior a la de alta en la sección actual (%s).' => 'Aldaketaren data ezin da uneko atalean alta eman zitzaion data baino lehenagokoa izan (%s).',
	'La fecha del cambio no puede ser posterior a hoy.' => 'Aldaketaren data ezin da gaur baino geroagokoa izan.',
	'%1$s, desde el %2$s' => '%1$s, %2$s(e)tik',
	'Ahora' => 'Orain',
	'Cambiar de sección' => 'Aldatu atalez',
	'Cambiar de sección en el CRM' => 'Aldatu atalez CRMan',
	'Comprobar y guardar' => 'Egiaztatu eta gorde',
	'Dar de baja en el CRM' => 'Eman baja CRMan',
	'Dar la membresía en el CRM' => 'Eman kidetza CRMan',
	'Deja de contar en la cuota de su familia (nº %s). Tesorería lo verá en «Bajas recientes».' => 'Bere familiaren kuotan kontatzeari uzten dio (%s zk.). Diruzaintzak «Azken bajak» atalean ikusiko du.',
	'Es la misma persona: guardar el documento igualmente.' => 'Pertsona bera da: gorde dokumentua hala ere.',
	'Fecha de alta' => 'Alta-data',
	'Fecha de baja' => 'Baja-data',
	'Fecha del cambio' => 'Aldaketaren data',
	'La fecha de baja es el día en que deja de estar en el grupo: desde ese día ya no cuenta como socio/a.' => 'Baja-data taldean egoteari uzten dion eguna da: egun horretatik aurrera ez da bazkidetzat hartzen.',
	'Las cuentas familiares que la representan (%s) dejarán de verla; si no representan a nadie más con membresía activa, tampoco podrán entrar.' => 'Hura ordezkatzen duten familia-kontuek (%s) ez dute gehiago ikusiko; kidetza aktiboa duen beste inor ordezkatzen ez badute, ezin izango dute sartu ere.',
	'Membresía activa:' => 'Kidetza aktiboa:',
	'Membresía en el CRM' => 'Kidetza CRMan',
	'Membresía que se cierra' => 'Ixten den kidetza',
	'Membresías que se cierran' => 'Ixten diren kidetzak',
	'No se borra nada: la ficha y sus membresías anteriores se quedan en el CRM. Si vuelve, se le da una membresía nueva.' => 'Ez da ezer ezabatzen: fitxa eta aurreko kidetzak CRMan geratzen dira. Itzultzen bada, kidetza berri bat ematen zaio.',
	'Nueva membresía' => 'Kidetza berria',
	'Para quien aún no lo tenía (por ejemplo, un menor que lo acaba de sacar). Antes de guardarlo se comprueba si ya está en otra ficha de tu grupo o en otro grupo u organización de Scouts de España.' => 'Oraindik ez zuenarentzat (adibidez, atera berri duen adingabe batentzat). Gorde aurretik egiaztatzen da zure taldeko beste fitxa batean edo Scouts de Españako beste talde edo erakunde batean dagoen.',
	'Para quien vuelve al grupo: la membresía nueva va en su ficha de siempre, con su mismo nº de socio/a. No se crea otra ficha.' => 'Taldera itzultzen denarentzat: kidetza berria betiko fitxan doa, bazkide-zenbaki berarekin. Ez da beste fitxarik sortzen.',
	'Poner el documento' => 'Jarri dokumentua',
	'Qué cambia con la baja:' => 'Zer aldatzen da bajarekin:',
	'Se cierra la membresía actual con el motivo «cambio de sección» y se abre otra en la sección nueva, con la misma fecha.' => 'Uneko kidetza «atal-aldaketa» arrazoiarekin ixten da eta beste bat irekitzen da atal berrian, data berarekin.',
	'Sección nueva' => 'Atal berria',
	'Su cuenta de acceso (%s) ya no podrá entrar en la web.' => 'Bere sarbide-kontuak (%s) ezin izango du webean sartu.',
	'Ya tiene una membresía activa (%s).' => 'Badu kidetza aktibo bat (%s).',
	'no puede entrar en la web ni cuenta en las cuotas.' => 'ezin da webean sartu eta ez da kuotetan kontatzen.',
	'¿Dar de baja a %s en el CRM?' => 'Baja eman %s pertsonari CRMan?',
	'← Ficha de %s' => '← %s: fitxa',
	'Elige la sección.' => 'Aukeratu atala.',
	'La fecha de alta no es válida.' => 'Alta-data ez da baliozkoa.',
	'%1$s ha quedado de baja en el CRM desde el %2$s.' => '%1$s bajan geratu da CRMan %2$s(e)tik.',
	'%1$s pasa a %2$s desde el %3$s. La membresía anterior queda cerrada con el motivo «cambio de sección».' => '%1$s %2$s atalera pasatzen da %3$s(e)tik. Aurreko kidetza «atal-aldaketa» arrazoiarekin itxita geratzen da.',
	'Deja de contar en la cuota de la familia nº %s: Tesorería lo verá en «Bajas recientes».' => '%s zk. familiaren kuotan kontatzeari uzten dio: Diruzaintzak «Azken bajak» atalean ikusiko du.',
	'Documento guardado en la ficha de %s.' => 'Dokumentua gordeta dago fitxan: %s.',
	'El usuario del CRM de tu grupo no tiene permiso para crear personas y membresías. Un administrador puede revisarlo en wp-admin → Grupos Scouts.' => 'Zure taldearen CRMko erabiltzaileak ez du baimenik pertsonak eta kidetzak sortzeko. Administratzaile batek wp-admin → Grupos Scouts atalean berrikus dezake.',
	'Ese documento también está dado de alta en otro grupo u organización de Scouts de España.' => 'Dokumentu horrek alta emanda du Scouts de Españako beste talde edo erakunde batean ere.',
	'Las cuentas familiares que la representan ya no la ven; si no representan a nadie más con membresía activa, tampoco pueden entrar.' => 'Hura ordezkatzen duten familia-kontuek ez dute gehiago ikusten; kidetza aktiboa duen beste inor ordezkatzen ez badute, ezin dira sartu ere.',
	'Membresía nueva en el CRM: %1$s, en %2$s desde el %3$s.' => 'Kidetza berria CRMan: %1$s, %2$s atalean %3$s(e)tik.',
	'Su cuenta de acceso a la web ya no puede entrar.' => 'Bere web-sarbideko kontuak ezin du sartu.',
	'%1$s ya es socio/a del grupo, en %2$s desde el %3$s.' => '%1$s taldeko bazkidea da orain, %2$s atalean %3$s(e)tik.',
	'Alta de socio/a' => 'Bazkide-alta',
	'Alta hecha en el CRM.' => 'Alta CRMan eginda.',
	'Comprobar y seguir' => 'Egiaztatu eta jarraitu',
	'Corregir los datos' => 'Zuzendu datuak',
	'Dar acceso a la web' => 'Eman web-sarbidea',
	'Dar de alta a otra persona' => 'Eman alta beste pertsona bati',
	'Dar de alta en el CRM' => 'Eman alta CRMan',
	'Darle una membresía nueva' => 'Eman kidetza berri bat',
	'Datos' => 'Datuak',
	'Desacuerdo' => 'Desadostasuna',
	'Documento' => 'Dokumentua',
	'El CRM todavía no le ha puesto el nº de socio/a. Lo verás en su ficha cuando lo tenga.' => 'CRMak oraindik ez dio bazkide-zenbakia jarri. Bere fitxan ikusiko duzu duenean.',
	'Empieza por su documento: se comprueba si ya tiene ficha, en tu grupo o en otro grupo u organización de Scouts de España.' => 'Hasi bere dokumentutik: fitxarik baduen egiaztatzen da, zure taldean edo Scouts de Españako beste talde edo erakunde batean.',
	'Es menor de %d años y no tiene documento' => '%d urte baino gutxiago ditu eta ez du dokumenturik',
	'Fallecimiento' => 'Heriotza',
	'Hecho' => 'Eginda',
	'Motivos económicos' => 'Arrazoi ekonomikoak',
	'Motivos personales' => 'Arrazoi pertsonalak',
	'No se ha podido comprobar si está en otros grupos u organizaciones: quiero darla de alta igualmente.' => 'Ezin izan da egiaztatu beste talde edo erakunde batzuetan dagoen: alta eman nahi diot hala ere.',
	'Obligatorio a partir de los %d años.' => 'Derrigorrezkoa %d urtetik aurrera.',
	'Otro motivo' => 'Beste arrazoi bat',
	'Revisa los datos. Al confirmar se crean su ficha y su membresía en el CRM de Scouts de España, y el CRM le da su nº de socio/a.' => 'Berrikusi datuak. Berrestean, bere fitxa eta kidetza sortzen dira Scouts de Españako CRMan, eta CRMak bazkide-zenbakia ematen dio.',
	'Se ha terminado un alta que se había quedado a medias: no se ha creado otra ficha.' => 'Erdizka geratu zen alta bat amaitu da: ez da beste fitxarik sortu.',
	'Sin documento' => 'Dokumenturik gabe',
	'Sé que ya está dada de alta en otro grupo u organización y quiero darla de alta también en el mío.' => 'Badakit beste talde edo erakunde batean alta emanda duela eta nirean ere alta eman nahi diot.',
	'Tutor/a %d' => '%d. tutorea',
	'Tutores legales (si es menor de edad)' => 'Legezko tutoreak (adingabea bada)',
	'Ver su ficha' => 'Ikusi bere fitxa',
	'Ya tiene ficha en tu grupo: no se crea otra.' => 'Badu fitxa zure taldean: ez da beste bat sortzen.',
	'Bajas recientes' => 'Azken bajak',
	'Personas de alguna familia dadas de baja en el CRM desde la web en los últimos 30 días: ya no cuentan en la cuota de su familia.' => 'Azken 30 egunetan webetik CRMan baja eman zaien familiaren bateko pertsonak: ez dira gehiago kontatzen beren familiaren kuotan.',
	'baja el %s' => 'baja: %s',
	'familia nº %s' => '%s zk. familia',

	// Altas en el CRM · tutores y aviso de baja por email (v0.23.1, doc 34)
	'Por debajo de %d años hace falta el tutor/a 1: nombre, apellidos y email.' => '%d urtetik behera 1. tutorea behar da: izena, abizenak eta emaila.',
	'Desde ese día ya no cuenta como socio/a del grupo ni en las cuotas, y su acceso al área privada se cierra. Su ficha se conserva: si algún día vuelve, solo hay que darle de alta de nuevo.' => 'Egun horretatik aurrera ez da taldeko bazkidetzat hartzen ez kuotetan kontatzen, eta eremu pribaturako sarbidea ixten zaio. Bere fitxa gordetzen da: egunen batean itzultzen bada, berriro alta ematea besterik ez dago.',
	'Es de la familia <strong>%s</strong>: desde la baja ya no cuenta en su cuota. Revisa si hay que ajustar algo en sus pagos.' => '<strong>%s</strong> familiakoa da: bajatik aurrera ez da bere kuotan kontatzen. Berrikusi ordainketetan zerbait doitu behar den.',
	'Ir a Tesorería' => 'Joan Diruzaintzara',
	'Motivo:' => 'Arrazoia:',
	'No está en ninguna familia de Tesorería.' => 'Ez dago Diruzaintzako familia batean ere.',
	'Se ha dado de baja en el CRM a <strong>%1$s</strong> (nº de socio/a %2$s) desde el <strong>%3$s</strong>.' => '<strong>%1$s</strong> (%2$s bazkide-zk.) bajan eman da CRMan <strong>%3$s</strong>(e)tik.',
	'Si es un error o tienes cualquier duda, escríbenos a %s.' => 'Akats bat bada edo zalantzaren bat baduzu, idatzi iezaguzu helbide honetara: %s.',
	'Si es un error o tienes cualquier duda, habla con la Secretaría del grupo.' => 'Akats bat bada edo zalantzaren bat baduzu, hitz egin taldeko Idazkaritzarekin.',
	'Te confirmamos que <strong>%1$s</strong> ha causado baja en el <strong>%2$s</strong> el %3$s.' => 'Baieztatzen dizugu <strong>%1$s</strong> bajan geratu dela <strong>%2$s</strong> taldean %3$s(e)an.',
	'Te llega porque tienes la responsabilidad de Tesorería en el área privada del grupo. Para verlo tendrás que iniciar sesión.' => 'Taldearen eremu pribatuan Diruzaintzaren ardura duzulako iristen zaizu. Ikusteko saioa hasi beharko duzu.',
	'¡Gracias por todo lo compartido!' => 'Eskerrik asko partekatutako guztiagatik!',
	'Se avisa por email a Tesorería y a la familia (o a la propia persona, si es mayor de edad). Con el motivo «Fallecimiento» no se escribe a la familia.' => 'Emailez abisatzen zaie Diruzaintzari eta familiari (edo pertsonari berari, adin nagusikoa bada). «Heriotza» arrazoiarekin ez zaio familiari idazten.',
	'%d no se han podido enviar (mira Usuarios → Emails).' => '%d ezin izan dira bidali (begiratu Erabiltzaileak → Emailak).',
	'Avisos por email: %1$d a Tesorería y %2$d a la familia.' => 'Abisuak emailez: %1$d Diruzaintzari eta %2$d familiari.',
	'No hay ningún email de la familia al que avisar.' => 'Ez dago familiaren emailik abisatzeko.',
	'Por el motivo de la baja, a la familia no se le ha escrito.' => 'Bajaren arrazoia dela eta, ez zaio familiari idatzi.',
	'Aviso de baja' => 'Baja-abisua',
	'Nº %s' => '%s zk.',
	'[%s] Baja de un socio/a en el CRM' => '[%s] Bazkide baten baja CRMan',
	'[%s] Confirmación de baja en el grupo' => '[%s] Taldeko bajaren baieztapena',

