	'Quién' => 'Nork',
	'Viene de un ingreso del banco: el ingreso volverá a estar por conciliar.' => 'Bankuko diru-sarrera batetik dator: diru-sarrera berriro egongo da bateratzeko.',
	'Viene del cobro de una remesa SEPA: la remesa lo seguirá dando por cobrado.' => 'SEPA remesa baten kobrantzatik dator: remesak kobratutzat ematen jarraituko du.',
