	// v0.29: informes en Excel e impresión, plegables, cambios agrupados, camisas del inventario
	'Aprobar los seleccionados' => 'Onartu hautatutakoak',
	'Cambios de %s' => '%s(r)en aldaketak',
	'De los últimos %d días. Solo se sabe qué datos se cambiaron, quién y cuándo: los valores no se guardan en la web.' => 'Azken %d egunetakoak. Zein datu aldatu ziren, nork aldatu zituen eta noiz bakarrik dakigu: balioak ez dira webean gordetzen.',
	'Documento de identidad' => 'Nortasun-agiria',
	'Documento puesto desde la ficha' => 'Fitxatik jarritako dokumentua',
	'Email de una solicitud de acceso' => 'Sarbide-eskaera baten emaila',
	'Guardado en la ficha' => 'Fitxan gordeta',
	'Hechos directamente en la ficha' => 'Fitxan zuzenean eginak',
	'Las propuestas ya revisadas y los cambios hechos directamente en las fichas por Secretaría, Coordinación o los scouters (de estos, los de los últimos %d días).' => 'Jada berrikusitako proposamenak eta Idazkaritzak, Koordinazioak edo scouterrek fitxetan zuzenean egindako aldaketak (azken horien kasuan, azken %d egunetakoak).',
	'Los cambios marcados se guardan en el CRM de una vez. Los que llevan ⚠️ (el dato del CRM ha cambiado desde la propuesta) vienen sin marcar: márcalos si quieres aplicarlos igualmente.' => 'Markatutako aldaketak CRMan gordetzen dira batera. ⚠️ daramatenak (CRMko datua proposamenaz geroztik aldatu da) markatu gabe daude: markatu itzazu hala ere aplikatu nahi badituzu.',
	'Los has propuesto tú: los revisa otra persona.' => 'Zuk proposatu dituzu: beste pertsona batek berrikusten ditu.',
	'Marcar el cambio de «%s»' => 'Markatu «%s»(r)en aldaketa',
	'Motivo (si los rechazas)' => 'Arrazoia (ukatzen badituzu)',
	'No hay cambios resueltos de esta persona.' => 'Pertsona honen ebatzitako aldaketarik ez dago.',
	'No quedan cambios pendientes de esta persona.' => 'Ez da geratzen pertsona honen zain dagoen aldaketarik.',
	'Propuestas revisadas' => 'Berrikusitako proposamenak',
	'Rechazar los seleccionados' => 'Ukatu hautatutakoak',
	'Revisar (%d)' => 'Berrikusi (%d)',
	'Ver la ficha' => 'Ikusi fitxa',
	'Último' => 'Azkena',
	'Último propuesto' => 'Azken proposatua',
	'← Cambios propuestos' => '← Proposatutako aldaketak',
	'Descargar Excel' => 'Deskargatu Excel',
	'Este informe incluye datos de salud: úsalos solo para la actividad, no los reenvíes y destruye las copias impresas al terminar.' => 'Txosten honek osasun-datuak barne hartzen ditu: erabili jarduerarako soilik, ez birbidali eta suntsitu kopia inprimatuak amaitzean.',
	'Impreso desde el área privada el %s.' => 'Eremu pribatutik inprimatua: %s.',
	'con membresía activa' => 'kidetza aktiboarekin',
	'solo con datos de salud relevantes' => 'osasun-datu garrantzitsuak dituztenak soilik',
	'Es el tipo de las camisas del uniforme: no se puede borrar (lo usa la gestión de uniformes).' => 'Uniformeko alkandoren mota da: ezin da ezabatu (uniformeen kudeaketak erabiltzen du).',
	'Las camisas del uniforme necesitan el modelo (chico o chica) y una talla de ese modelo.' => 'Uniformeko alkandorek eredua (mutila edo neska) eta eredu horretako neurri bat behar dituzte.',
	'Modelo (camisas)' => 'Eredua (alkandorak)',
	'Solo para el tipo «Camisa uniforme»: la gestión de uniformes asigna estas camisas a los pedidos y las descuenta de aquí. Si no escribes la descripción, se pone sola.' => '«Camisa uniforme» motarentzat soilik: uniformeen kudeaketak alkandora hauek eskaerei esleitzen dizkie eta hemendik kentzen ditu. Deskribapena idazten ez baduzu, berez ezartzen da.',
	'Talla (camisas)' => 'Neurria (alkandorak)',
	'chica' => 'neska',
	'%d cambio aprobado y guardado en el CRM.' => '%d aldaketa onartu eta CRMan gorde da.',
	'%d cambio no se ha aplicado: el dato del CRM ha cambiado desde que se propuso. Revísalo y márcalo otra vez si quieres aplicarlo igualmente.' => '%d aldaketa ez da aplikatu: CRMko datua proposatu zenetik aldatu da. Berrikusi eta markatu berriro hala ere aplikatu nahi baduzu.',
	'%d cambio rechazado. Quien lo propuso verá el motivo en la ficha.' => '%d aldaketa ukatu da. Proposatu zuenak arrazoia fitxan ikusiko du.',
	'%d cambios aprobados y guardados en el CRM.' => '%d aldaketa onartu eta CRMan gorde dira.',
	'%d cambios no se han aplicado: el dato del CRM ha cambiado desde que se propusieron. Revísalos y márcalos otra vez si quieres aplicarlos igualmente.' => '%d aldaketa ez dira aplikatu: CRMko datua proposatu zirenetik aldatu da. Berrikusi eta markatu berriro hala ere aplikatu nahi badituzu.',
	'%d cambios rechazados. Quien los propuso verá el motivo en la ficha.' => '%d aldaketa ukatu dira. Proposatu zituenak arrazoia fitxan ikusiko du.',
	'Camisa asignada a %1$s y descontada del inventario (pedido %2$s).' => 'Alkandora %1$s(r)i esleitu zaio eta inbentariotik kendu da (%2$s eskaera).',
	'Elige a quién se le da la camisa (un socio/a con membresía activa).' => 'Aukeratu nori ematen zaion alkandora (kidetza aktiboa duen bazkide bat).',
	'La camisa del pedido %s ha vuelto al inventario.' => '%s eskaerako alkandora inbentariora itzuli da.',
	'La camisa del pedido %s sale del inventario: se ha descontado una.' => '%s eskaerako alkandora inbentariotik ateratzen da: bat kendu da.',
	'Marca los cambios que quieres aprobar o rechazar.' => 'Markatu onartu edo ukatu nahi dituzun aldaketak.',
	'No puedes revisar los cambios de esa persona.' => 'Ezin dituzu pertsona horren aldaketak berrikusi.',
	'Contraer o expandir «%s»' => 'Tolestu edo zabaldu «%s»',
	'Versión para imprimir' => 'Inprimatzeko bertsioa',
	'%1$d con membresía activa · %2$d sin membresía activa' => '%1$d kidetza aktiboarekin · %2$d kidetza aktiborik gabe',
	'(tipo «Camisa uniforme», con su modelo y su talla).' => '(«Camisa uniforme» mota, bere eredu eta neurriarekin).',
	'Asignar una camisa' => 'Esleitu alkandora bat',
	'Asignar una camisa del inventario' => 'Esleitu inbentarioko alkandora bat',
	'Asignar y descontar del inventario' => 'Esleitu eta inbentariotik kendu',
	'Añádelas en el inventario' => 'Gehitu itzazu inbentariora',
	'Camisa' => 'Alkandora',
	'Camisa del inventario' => 'Inbentarioko alkandora',
	'Camisas del inventario' => 'Inbentarioko alkandorak',
	'Del inventario del grupo' => 'Taldearen inbentariokoa',
	'Devolver la camisa al inventario' => 'Itzuli alkandora inbentariora',
	'Hay en el inventario' => 'Inbentarioan dago',
	'La camisa de este pedido no se puede devolver al inventario.' => 'Eskaera honetako alkandora ezin da inbentariora itzuli.',
	'La camisa de este pedido no se puede servir del inventario.' => 'Eskaera honetako alkandora ezin da inbentariotik hornitu.',
	'Las camisas que el grupo tiene guardadas. Un pedido con camisa que aún no está en el pedido al proveedor se puede servir de aquí («Hay en el inventario»: ábrelo y pulsa «Servir del inventario»). Para dar una camisa a quien no la ha pedido, «Asignar una camisa».' => 'Taldeak gordeta dituen alkandorak. Hornitzaileari egindako eskaeran oraindik sartuta ez dagoen alkandora duen eskaera bat hemendik hornitu daiteke («Inbentarioan dago»: ireki eta sakatu «Hornitu inbentariotik»). Eskatu ez duen norbaiti alkandora bat emateko, «Esleitu alkandora bat».',
	'Las insignias sí van en el pedido al proveedor.' => 'Insigniak, ordea, hornitzaileari egindako eskaeran doaz.',
	'No hay camisas en el inventario.' => 'Ez dago alkandorarik inbentarioan.',
	'No hay camisas en el inventario. Añádelas en el inventario con el tipo «Camisa uniforme», su modelo y su talla.' => 'Ez dago alkandorarik inbentarioan. Gehitu itzazu inbentariora «Camisa uniforme» motarekin, bere eredu eta neurriarekin.',
	'No queda ninguna camisa «%1$s» de la talla %2$s en el inventario.' => 'Ez da geratzen «%1$s» alkandorarik %2$s neurrian inbentarioan.',
	'O, sin pedirla al proveedor: en el inventario queda %2$d camisa «%1$s».' => 'Edo, hornitzaileari eskatu gabe: inbentarioan %2$d alkandora geratzen da («%1$s»).',
	'O, sin pedirla al proveedor: en el inventario quedan %2$d camisas «%1$s».' => 'Edo, hornitzaileari eskatu gabe: inbentarioan %2$d alkandora geratzen dira («%1$s»).',
	'Para dar a alguien una camisa que el grupo ya tiene guardada, sin que la haya pedido: se crea su pedido, ya servido del inventario, y se descuenta la camisa. Después se entrega y se cobra como cualquier otro pedido.' => 'Taldeak gordeta duen alkandora bat eskatu ez duen norbaiti emateko: bere eskaera sortzen da, jada inbentariotik hornituta, eta alkandora kentzen da. Gero, beste edozein eskaera bezala, entregatu eta kobratu egiten da.',
	'Para quién' => 'Nori',
	'Servir del inventario' => 'Hornitu inbentariotik',
	'Sin sección' => 'Atalik gabe',
	'Talla %1$s · queda %2$d' => 'Neurria %1$s · %2$d geratzen da',
	'Talla %1$s · quedan %2$d' => 'Neurria %1$s · %2$d geratzen dira',
	'Ver en el inventario' => 'Ikusi inbentarioan',
	'chico' => 'mutila',
	'¿Devolver la camisa al inventario? El pedido vuelve a quedar pendiente de pedir.' => 'Alkandora inbentariora itzuli nahi duzu? Eskaera berriro eskatzeko zain geratzen da.',
	'Ábrelo y pulsa «Servir del inventario»' => 'Ireki eta sakatu «Hornitu inbentariotik»',

	// v0.29: informe «Fichas reducidas» (una ficha por página)
	'Fichas reducidas' => 'Fitxa laburrak',
	'Las del informe' => 'Txostenekoak',
	'Presentación' => 'Aurkezpena',
	'Tabla' => 'Taula',
	'Una ficha por persona (al imprimir, una por página)' => 'Fitxa bat pertsonako (inprimatzean, bat orrialdeko)',

	// v0.29: primera camisa de scouter gratis
	'La primera camisa de cada scouter es gratis (desde la segunda, paga el precio)' => 'Scouter bakoitzaren lehen alkandora doakoa da (bigarrenetik aurrera, prezioa ordaintzen du)',
	'La primera camisa de cada scouter es gratis; desde la segunda, se paga el precio.' => 'Scouter bakoitzaren lehen alkandora doakoa da; bigarrenetik aurrera, prezioa ordaintzen da.',
	'Precio: %s.' => 'Prezioa: %s.',
	'Precio: %s. A un scouter, su primera camisa es gratis (el pedido queda pagado «sin coste»); desde la segunda, paga el precio.' => 'Prezioa: %s. Scouter batentzat, bere lehen alkandora doakoa da (eskaera «kosturik gabe» ordainduta geratzen da); bigarrenetik aurrera, prezioa ordaintzen du.',
	'Sin coste: primera camisa de scouter' => 'Kosturik gabe: scouterraren lehen alkandora',

	// v0.29: respuestas del usuario
	'Una página por socio/a con su móvil, su tutor/a y su móvil, la cesión de imagen, las alergias, la alimentación y las enfermedades. Elige la sección al verlo.' => 'Orrialde bat bazkide bakoitzeko: mugikorra, tutorea eta haren mugikorra, irudiaren lagapena, alergiak, elikadura eta gaixotasunak. Aukeratu atala ikustean.',
	'Eliminar un pago o un ajuste lo hace Tesorería.' => 'Ordainketa edo doikuntza bat ezabatzea Diruzaintzak egiten du.',
	'Servir y asignar camisas del inventario lo hacen Coordinación y Tesorería.' => 'Inbentarioko alkandorak hornitu eta esleitzea Koordinazioak eta Diruzaintzak egiten dute.',

	// v0.30: inventario (material nuevo, comprada, email de revisión, importar repetidos) y uniforme para la sección
	'Cuando hayas comprado el material, márcala como comprada en el área privada: lo comprado se sumará al inventario.' => 'Materiala erosi duzunean, markatu zerrenda erosita gisa eremu pribatuan: erositakoa inbentarioari gehituko zaio.',
	'La ha revisado %s.' => '%s(e)k berrikusi du.',
	'Material nuevo (no está en el inventario)' => 'Material berria (ez dago inbentarioan)',
	'Si hace falta, prepara otra lista con los cambios.' => 'Behar izanez gero, prestatu beste zerrenda bat aldaketekin.',
	'Te llega porque pediste esta lista de compra en el área privada del grupo. Para verla tendrás que iniciar sesión.' => 'Taldearen eremu pribatuan erosketa-zerrenda hau eskatu zenuelako jaso duzu. Ikusteko saioa hasi beharko duzu.',
	'Tesorería <strong>no ha dado el visto bueno</strong> a tu lista de compra de material <strong>%s</strong>: la ha rechazado.' => 'Diruzaintzak <strong>ez dio oniritzia eman</strong> zure <strong>%s</strong> material-erosketako zerrendari: ukatu egin du.',
	'Tesorería ha dado el <strong>visto bueno</strong> a tu lista de compra de material <strong>%s</strong>. Ya la puedes descargar en PDF para imprimirla.' => 'Diruzaintzak <strong>oniritzia</strong> eman dio zure <strong>%s</strong> material-erosketako zerrendari. Orain PDFan deskarga dezakezu inprimatzeko.',
	'Ver la lista' => 'Ikusi zerrenda',
	'Añadir otra línea' => 'Gehitu beste lerro bat',
	'Comprada' => 'Erosita',
	'Comprada: la marcó %1$s el %2$s. Lo comprado se sumó al inventario.' => 'Erosita: %1$s(e)k markatu zuen, %2$s. Erositakoa inbentarioari gehitu zitzaion.',
	'Cuando el material de la lista esté comprado, márcala como comprada: las cantidades se sumarán al inventario y el material nuevo se dará de alta. No se puede deshacer.' => 'Zerrendako materiala erosita dagoenean, markatu erosita gisa: kopuruak inbentarioari gehituko zaizkio eta material berriari alta emango zaio. Ezin da desegin.',
	'Dado de alta en el inventario' => 'Inbentarioan alta emanda',
	'Escribe qué material nuevo hay que comprar en la línea %d (o deja en blanco su precio).' => 'Idatzi zer material berri erosi behar den %d. lerroan (edo utzi prezioa hutsik).',
	'Esta lista no se puede marcar como comprada: tiene que tener el visto bueno de Tesorería y no estar ya comprada.' => 'Zerrenda hau ezin da erosita gisa markatu: Diruzaintzaren oniritzia izan behar du eta ez egon dagoeneko erosita.',
	'Lista %s marcada como comprada.' => '%s zerrenda erosita gisa markatu da.',
	'Lista de material nuevo' => 'Material berriaren zerrenda',
	'Marca el material que hay que comprar (lo que todavía no está en el inventario lo podrás escribir en la lista). Si de alguno ya hay %d unidades o más, te preguntaremos si de verdad hace falta comprar más. La lista la tiene que aprobar Tesorería antes de imprimirla.' => 'Markatu erosi behar den materiala (inbentarioan oraindik ez dagoena zerrendan idatzi ahal izango duzu). Materialen batetik %d unitate edo gehiago badaude, benetan gehiago erosi behar den galdetuko dizugu. Zerrenda Diruzaintzak onartu behar du inprimatu aurretik.',
	'Marcar como comprada' => 'Markatu erosita gisa',
	'Material nuevo' => 'Material berria',
	'Material nuevo, línea %d' => 'Material berria, %d. lerroa',
	'No has marcado ningún material del inventario. Puedes preparar la lista solo con material nuevo (aquí debajo) o volver al inventario y marcar lo que hay que comprar.' => 'Ez duzu inbentarioko materialik markatu. Zerrenda material berriarekin bakarrik presta dezakezu (hemen behean) edo inbentariora itzuli eta erosi behar dena markatu.',
	'No se ha podido enviar el email a quien la pidió: díselo tú.' => 'Ezin izan zaio emaila bidali eskatu zuenari: esaiozu zuk.',
	'Ojo: ya hay %d unidad en el inventario. ¿Seguro que hace falta comprar más?' => 'Kontuz: inbentarioan dagoeneko %d unitate dago. Ziur gehiago erosi behar dela?',
	'Ojo: ya hay %d unidades en el inventario. ¿Seguro que hace falta comprar más?' => 'Kontuz: inbentarioan dagoeneko %d unitate daude. Ziur gehiago erosi behar dela?',
	'Precio estimado, línea %d (opcional)' => 'Prezio estimatua, %d. lerroa (aukerakoa)',
	'Quien la pidió no tiene email en el área privada: díselo tú.' => 'Eskatu zuenak ez du emailik eremu pribatuan: esaiozu zuk.',
	'Qué hay que comprar' => 'Zer erosi behar den',
	'Se ha avisado por email a quien la pidió.' => 'Emailez abisatu zaio eskatu zuenari.',
	'Se ha dado de alta %d material nuevo.' => '%d material berriri alta eman zaio.',
	'Se ha sumado lo comprado a %d material del inventario.' => 'Erositakoa inbentarioko %d materiali gehitu zaio.',
	'Se ha sumado lo comprado a %d materiales del inventario.' => 'Erositakoa inbentarioko %d materiali gehitu zaie.',
	'Se han dado de alta %d materiales nuevos.' => '%d material berriri alta eman zaie.',
	'Se preparan marcando el material en el inventario (y escribiendo el que todavía no está). Tesorería recibe un email y le da el visto bueno; solo entonces se puede descargar el PDF para imprimirla. Quien la pidió recibe un email con la respuesta. Cuando el material esté comprado, se marca la lista como comprada y lo comprado se suma al inventario.' => 'Inbentarioan materiala markatuz prestatzen dira (eta oraindik ez dagoena idatziz). Diruzaintzak email bat jasotzen du eta oniritzia ematen dio; orduan bakarrik deskarga daiteke PDFa inprimatzeko. Eskatu zuenak erantzuna jasotzen du emailez. Materiala erosita dagoenean, zerrenda erosita gisa markatzen da eta erositakoa inbentarioari gehitzen zaio.',
	'Si hay que comprar algo que todavía no está en el inventario, escríbelo aquí. Cuando la lista se marque como comprada, se dará de alta en el inventario.' => 'Inbentarioan oraindik ez dagoen zerbait erosi behar bada, idatzi hemen. Zerrenda erosita gisa markatzen denean, inbentarioan alta emango zaio.',
	'Sin nº de serie, una fila con la misma descripción y el mismo tipo que un material que ya está en el inventario (o que otra fila del fichero) suma su cantidad a ese material en vez de crear otro. Las camisas del uniforme, solo si coinciden también el modelo y la talla.' => 'Serie-zenbakirik gabe, inbentarioan dagoen material baten (edo fitxategiko beste errenkada baten) deskribapen eta mota berak dituen errenkadak bere kopurua material horri gehitzen dio, beste bat sortu beharrean. Uniformeko alkandorak, eredua eta neurria ere bat badatoz bakarrik.',
	'Total estimado:' => 'Guztira (estimatua):',
	'Unidades a comprar, línea %d' => 'Erosteko unitateak, %d. lerroa',
	'Ya hay un material con esta descripción y este tipo, y sumándole esta cantidad pasaría de %d unidades.' => 'Badago deskribapen eta mota hau duen material bat, eta kopuru hau gehituta %d unitate baino gehiago izango lituzke.',
	'[%1$s] Tesorería ha rechazado tu lista de compra %2$s' => '[%1$s] Diruzaintzak zure %2$s erosketa-zerrenda ukatu du',
	'[%1$s] Tu lista de compra %2$s tiene el visto bueno de Tesorería' => '[%1$s] Zure %2$s erosketa-zerrendak Diruzaintzaren oniritzia du',
	'fila sumada a un material que ya estaba (misma descripción y tipo)' => 'lehendik zegoen material bati gehitutako errenkada (deskribapen eta mota bera)',
	'filas sumadas a un material que ya estaba (misma descripción y tipo)' => 'lehendik zegoen material bati gehitutako errenkadak (deskribapen eta mota bera)',
	'opcional' => 'aukerakoa',
	'¿Marcar la lista %s como comprada? Las cantidades se sumarán al inventario y el material nuevo se dará de alta. No se puede deshacer.' => '%s zerrenda erosita gisa markatu? Kopuruak inbentarioari gehituko zaizkio eta material berriari alta emango zaio. Ezin da desegin.',
	'¿Ya se ha comprado?' => 'Erosita dago jada?',
	'No has marcado ningún material del inventario. ¿Preparar una lista solo con material nuevo?' => 'Ez duzu inbentarioko materialik markatu. Material berriarekin bakarrik zerrenda bat prestatu?',
	'Ya hay %s unidades de «%s» en el inventario. ¿Seguro que hace falta comprar más?' => 'Inbentarioan dagoeneko %s unitate daude «%s» materialetik. Ziur gehiago erosi behar dela?',
	'Ya hay 1 unidad de «%s» en el inventario. ¿Seguro que hace falta comprar más?' => 'Inbentarioan dagoeneko unitate 1 dago «%s» materialetik. Ziur gehiago erosi behar dela?',
	'Como scouter, también puedes pedirlo para los socios y socias de tus secciones. El precio de la camisa es el de la persona para la que es.' => 'Scouter gisa, zure ataletako bazkideentzat ere eska dezakezu. Alkandoraren prezioa norentzat den pertsonarena da.',
	'Tu familia' => 'Zure familia',
	'Tú' => 'Zu',
	'Lista de compra revisada' => 'Berrikusitako erosketa-zerrenda',

	// v0.31: cambio de sección y cuota
	'Desde %1$s solo se puede pasar a %2$s, la siguiente por edad (solo los scouters cambian a cualquier sección).' => '%1$s ataletik %2$s atalera bakarrik pasa daiteke, adinagatik hurrengoa (scouterrek bakarrik alda dezakete edozein atalera).',
	'Un educando pasa a la siguiente sección por edad.' => 'Hezigaia adinagatik hurrengo atalera pasatzen da.',
	'%d hijo/a' => '%d seme-alaba',
	'%d hijos/as' => '%d seme-alaba',
	'ajuste %s' => 'doikuntza %s',

	// v0.32: lista de espera
	'El enlace para apuntarse a la lista de espera, la lista para el equipo y el paso al CRM.' => 'Itxaron-zerrendan izena emateko esteka, ekipoarentzako zerrenda eta CRMrako urratsa.',
	'Si el botón no funciona, copia esta dirección en el navegador:' => 'Botoiak funtzionatzen ez badu, kopiatu helbide hau nabigatzailean:',
	'¿Dudas? Escríbenos a %s.' => 'Zalantzarik? Idatzi iezaguzu %s helbidera.',
	'Quién quiere entrar en el grupo, la sección que le toca por edad y su paso al CRM.' => 'Nor sartu nahi den taldean, adinagatik dagokion atala eta CRMrako urratsa.',
	'persona en la lista de espera sin contactar' => 'pertsona itxaron-zerrendan kontaktatu gabe',
	'personas en la lista de espera sin contactar' => 'pertsona itxaron-zerrendan kontaktatu gabe',
	'Contactada' => 'Kontaktatua',
	'Descartada' => 'Baztertua',
	'En espera' => 'Zain',
	'Plaza ofrecida' => 'Plaza eskainia',
	'Sin confirmar el email' => 'Emaila berretsi gabe',
	'Lista de espera' => 'Itxaron-zerrenda',
	'%1$s ya está en la lista de espera del %2$s. Te hemos enviado un email con el enlace para ver tus datos.' => '%1$s dagoeneko %2$s(r)en itxaron-zerrendan dago. Email bat bidali dizugu zure datuak ikusteko estekarekin.',
	'%d inscripciones' => '%d izen-emate',
	'%d inscripción' => '%d izen-emate',
	'Abre el «Alta de socio/a» con sus datos. Primero se comprueba su documento en el CRM (si ya tiene ficha en el grupo, el alta se para). Al terminar el alta, esta inscripción se borra de la lista.' => 'Ireki «Bazkide-alta» bere datuekin. Lehenik, bere dokumentua CRMn egiaztatzen da (taldean dagoeneko fitxa badu, alta gelditu egiten da). Alta amaitzean, izen-emate hau zerrendatik ezabatzen da.',
	'Acepto que el %1$s guarde estos datos, cifrados, para gestionar la lista de espera durante %2$d meses (o hasta que me dé de alta o los borre). Solo los ve el equipo del grupo.' => 'Onartzen dut %1$s(e)k datu hauek zifratuta gordetzea itxaron-zerrenda kudeatzeko %2$d hilabetez (edo alta eman didaten edo ezabatu ditudan arte). Taldeko ekipoak soilik ikusten ditu.',
	'Apellidos de la persona de contacto' => 'Kontaktu-pertsonaren abizenak',
	'Apuntada más de una vez con distinto email' => 'Izena behin baino gehiagotan eman du, email desberdinekin',
	'Apuntar a otra persona' => 'Beste pertsona baten izena eman',
	'Apuntar el contacto' => 'Kontaktua erregistratu',
	'Apuntar un contacto hecho por otra vía' => 'Beste bide batetik egindako kontaktu bat erregistratu',
	'Apuntarme a la lista de espera' => 'Itxaron-zerrendan izena eman',
	'Apúntate a la lista de espera del %s. Te avisaremos cuando haya plaza.' => 'Eman izena %s(r)en itxaron-zerrendan. Plaza dagoenean abisatuko dizugu.',
	'Asignar' => 'Esleitu',
	'Aún sin edad' => 'Oraindik adinik gabe',
	'Borrar de la lista' => 'Ezabatu zerrendatik',
	'Borrar mis datos' => 'Ezabatu nire datuak',
	'Cambiar el estado' => 'Aldatu egoera',
	'Confirma la inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong>.' => 'Berretsi <strong>%1$s</strong>(r)en izen-ematea <strong>%2$s</strong>(r)en itxaron-zerrendan.',
	'Confirmar la inscripción' => 'Berretsi izen-ematea',
	'Contactar' => 'Kontaktatu',
	'Contacto por email' => 'Email bidezko kontaktua',
	'Contacto por teléfono' => 'Telefono bidezko kontaktua',
	'Cómo' => 'Nola',
	'DNI o NIE' => 'NAN edo AIZ',
	'El email con el que te apuntaste' => 'Izena emateko erabili zenuen emaila',
	'El enlace vale %d días. Si no has sido tú, ignora este correo: la inscripción se borrará sola.' => 'Esteka %d egunez da baliozkoa. Zu izan ez bazara, ez ikusi egin mezu honi: izen-ematea bere kabuz ezabatuko da.',
	'Email enviado: «%s»' => 'Emaila bidali da: «%s»',
	'En la lista' => 'Zerrendan',
	'En la lista desde' => 'Zerrendan noiztik',
	'Enviar email' => 'Bidali emaila',
	'Enviarme mis enlaces' => 'Bidali iezadazu nire estekak',
	'Escribe un teléfono válido (al menos 9 cifras).' => 'Idatzi baliozko telefono zenbaki bat (gutxienez 9 zifra).',
	'Estado: %s' => 'Egoera: %s',
	'Estas son las inscripciones con este email en la lista de espera del <strong>%s</strong>:' => 'Hauek dira email honekin <strong>%s</strong>(r)en itxaron-zerrendan dauden izen-emateak:',
	'Este enlace no es válido o la inscripción ya no está en la lista (se borra al darse de alta en el grupo, al pedirlo o a los %d meses).' => 'Esteka hau ez da baliozkoa edo izen-ematea ez dago jada zerrendan (taldean alta ematean, eskatzean edo %d hilabetera ezabatzen da).',
	'Este enlace no es válido o ya no está en uso. Pide el enlace actual a tu grupo scout.' => 'Esteka hau ez da baliozkoa edo jada ez da erabiltzen. Eskatu uneko esteka zure eskaut taldeari.',
	'Guarda este correo. Para ver tus datos te pediremos este email; desde ahí puedes mantenerlos o borrarlos cuando quieras.' => 'Gorde mezu hau. Zure datuak ikusteko email hau eskatuko dizugu; handik nahi duzunean mantendu edo ezabatu ditzakezu.',
	'Guardamos tus datos hasta' => 'Zure datuak noiz arte gordetzen ditugun',
	'Guardamos tus datos, cifrados, hasta el %s. Antes te avisaremos para que puedas mantenerlos.' => 'Zure datuak zifratuta gordetzen ditugu %s arte. Aurretik abisatuko dizugu, mantendu ahal izan ditzazun.',
	'Hecho: guardamos tus datos hasta el %s.' => 'Eginda: zure datuak %s arte gordetzen ditugu.',
	'Hemos recibido la inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong>.' => '<strong>%1$s</strong>(r)en izen-ematea jaso dugu <strong>%2$s</strong>(r)en itxaron-zerrendan.',
	'Historial' => 'Historia',
	'Inscripción confirmada.' => 'Izen-ematea berretsita.',
	'Inscripción en la lista de espera del <strong>%s</strong>.' => 'Izen-ematea <strong>%s</strong>(r)en itxaron-zerrendan.',
	'La de su edad' => 'Bere adinari dagokiona',
	'La de su edad (%s)' => 'Bere adinari dagokiona (%s)',
	'La inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong> está confirmada. Nos pondremos en contacto contigo cuando haya plaza.' => '<strong>%1$s</strong>(r)en izen-ematea <strong>%2$s</strong>(r)en itxaron-zerrendan berretsita dago. Plaza dagoenean zurekin harremanetan jarriko gara.',
	'La inscripción no tiene un email válido.' => 'Izen-emateak ez du baliozko emailik.',
	'Los datos de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong> se borrarán el <strong>%3$s</strong>.' => '<strong>%1$s</strong>(r)en datuak <strong>%2$s</strong>(r)en itxaron-zerrendan ezabatuko dira, ondoko egunean: <strong>%3$s</strong>.',
	'Mantener mis datos' => 'Mantendu nire datuak',
	'Mantener mis datos %d meses más' => 'Mantendu nire datuak %d hilabete gehiagoz',
	'Mensaje' => 'Mezua',
	'No hay nadie en la lista de espera con este filtro.' => 'Ez dago inor itxaron-zerrendan iragazki honekin.',
	'Nombre de la persona de contacto' => 'Kontaktu-pertsonaren izena',
	'Observaciones' => 'Oharrak',
	'Para apuntarte tienes que aceptar el tratamiento de los datos.' => 'Izena emateko, datuen tratamendua onartu behar duzu.',
	'Para corregir algún dato, escribe a tu grupo o borra la inscripción y vuelve a apuntarte con el enlace del grupo.' => 'Daturen bat zuzentzeko, idatzi zure taldeari edo ezabatu izen-ematea eta eman izena berriro taldearen estekarekin.',
	'Para que entre en la lista, confirma que este email es tuyo:' => 'Zerrendan sar dadin, berretsi email hau zurea dela:',
	'Para ver tus datos de la lista de espera, escribe el email con el que te apuntaste.' => 'Itxaron-zerrendako zure datuak ikusteko, idatzi izena emateko erabili zenuen emaila.',
	'Pasa este enlace a quien quiera entrar en el grupo. Deja sus datos, confirma su email y aparece aquí. Sus datos se guardan cifrados y se borran al darle de alta, si lo pide o a los 12 meses (salvo que diga que los mantiene).' => 'Pasatu esteka hau taldean sartu nahi duenari. Bere datuak uzten ditu, bere emaila berresten du eta hemen agertzen da. Bere datuak zifratuta gordetzen dira eta alta ematean, eskatzen duenean edo 12 hilabetera ezabatzen dira (mantentzen dituela esaten ez badu).',
	'Persona de contacto' => 'Kontaktu-pertsona',
	'Por debajo de %d años, escribe el nombre y los apellidos de la madre, el padre o el tutor/a.' => '%d urtetik behera, idatzi amaren, aitaren edo tutorearen izena eta abizenak.',
	'Puedes responder a este correo. Estás en la lista de espera del %1$s: <a href="%2$s">ver mis datos</a>.' => 'Mezu honi erantzun diezaiokezu. %1$s(r)en itxaron-zerrendan zaude: <a href="%2$s">ikusi nire datuak</a>.',
	'Quiero borrar mis datos y salir de la lista de espera. No se puede deshacer.' => 'Nire datuak ezabatu eta itxaron-zerrendatik atera nahi dut. Ezin da desegin.',
	'Quién quiere entrar en el grupo' => 'Nor sartu nahi den taldean',
	'Repetida' => 'Errepikatua',
	'Se apuntó' => 'Izena eman zuen',
	'Se envía desde la web con el email de contacto del grupo para las respuestas, queda en el historial y la inscripción pasa a «Contactada».' => 'Webetik bidaltzen da, taldearen kontaktu-emailarekin erantzunetarako, historian gelditzen da eta izen-ematea «Kontaktatua» egoerara pasatzen da.',
	'Sección asignada' => 'Esleitutako atala',
	'Sección asignada: %s' => 'Esleitutako atala: %s',
	'Sección por edad' => 'Adinaren araberako atala',
	'Sección y alta' => 'Atala eta alta',
	'Sección: la de su edad' => 'Atala: bere adinari dagokiona',
	'Si %s está en alguna lista de espera, te hemos enviado un email con tus enlaces.' => '%s itxaron-zerrendaren batean badago, email bat bidali dizugu zure estekekin.',
	'Si el enlace ha llegado a quien no debía. Los enlaces personales de cada inscripción siguen valiendo.' => 'Esteka ez zegokionarengana iritsi bada. Izen-emate bakoitzaren esteka pertsonalek indarrean jarraitzen dute.',
	'Si es menor de %d años, los datos de la madre, el padre o el tutor/a.' => '%d urte baino gutxiagokoa bada, amaren, aitaren edo tutorearen datuak.',
	'Si no haces nada, se borrarán ese día y saldrás de la lista.' => 'Ezer egiten ez baduzu, egun horretan ezabatuko dira eta zerrendatik aterako zara.',
	'Si no has pedido tú estos enlaces, puedes ignorar este correo.' => 'Esteka hauek zuk eskatu ez badituzu, mezu hau ez ikusi egin dezakezu.',
	'Si no te llega, mira en el correo no deseado. El enlace vale %d días.' => 'Ez bazaizu iristen, begiratu spam karpetan. Esteka %d egunez da baliozkoa.',
	'Si quieres seguir en la lista, entra y pulsa «Mantener mis datos»: los guardaremos %d meses más.' => 'Zerrendan jarraitu nahi baduzu, sartu eta sakatu «Mantendu nire datuak»: %d hilabete gehiagoz gordeko ditugu.',
	'Sus datos se borran el' => 'Datuak ezabatzen diren eguna',
	'Sí (lo ven Secretaría y Coordinación)' => 'Bai (Idazkaritzak eta Koordinazioak ikusten dute)',
	'Te enviaremos un email para confirmarlo. Es también tu clave para ver tus datos más adelante.' => 'Email bat bidaliko dizugu berresteko. Zure datuak geroago ikusteko gakoa ere bada.',
	'Te hemos enviado un email a %s para confirmar la inscripción. Hasta que no pulses su enlace, no entra en la lista.' => 'Email bat bidali dizugu %s helbidera izen-ematea berresteko. Bere esteka sakatzen ez duzun arte, ez da zerrendan sartzen.',
	'Te hemos enviado un email para confirmar la inscripción. Hasta que no pulses su enlace, no entra en la lista.' => 'Email bat bidali dizugu izen-ematea berresteko. Bere esteka sakatzen ez duzun arte, ez da zerrendan sartzen.',
	'Teléfono' => 'Telefonoa',
	'Todavía no ha confirmado su email: no entra en la lista hasta que lo haga. Si no lo confirma en %d días, se borra sola.' => 'Oraindik ez du bere emaila berretsi: berretsi arte ez da zerrendan sartzen. %d egunetan berresten ez badu, bere kabuz ezabatzen da.',
	'Tus datos se han borrado y ya no estás en la lista de espera.' => 'Zure datuak ezabatu dira eta ez zaude jada itxaron-zerrendan.',
	'Ver mis datos' => 'Ikusi nire datuak',
	'[%s] Confirma la inscripción en la lista de espera' => '[%s] Berretsi itxaron-zerrendako izen-ematea',
	'[%s] Inscripción confirmada en la lista de espera' => '[%s] Izen-ematea berretsi da itxaron-zerrendan',
	'[%s] Tus datos de la lista de espera caducan pronto' => '[%s] Itxaron-zerrendako zure datuak laster iraungiko dira',
	'[%s] Tus enlaces de la lista de espera' => '[%s] Itxaron-zerrendako zure estekak',
	'asignada' => 'esleituta',
	'confirmó el %s' => 'berretsi zuen: %s',
	'sin confirmar: el enlace la confirma' => 'berretsi gabe: estekak berresten du',
	'¿Borrar a %s de la lista de espera? Sus datos se borran y no se puede deshacer.' => '%s itxaron-zerrendatik ezabatu nahi duzu? Bere datuak ezabatzen dira eta ezin da desegin.',
	'¿Ya estás en la lista? Recibe tus enlaces' => 'Dagoeneko zerrendan zaude? Jaso zure estekak',
	'Último contacto: %1$s, %2$s' => 'Azken kontaktua: %1$s, %2$s',
	'← Lista de espera' => '← Itxaron-zerrenda',
	'Contacto apuntado.' => 'Kontaktua erregistratu da.',
	'Email enviado a %s.' => 'Emaila bidali da %s helbidera.',
	'Enlace de la lista de espera renovado: el anterior ya no sirve.' => 'Itxaron-zerrendaren esteka berritu da: aurrekoak ez du jada balio.',
	'Esa inscripción ya no está en la lista de espera.' => 'Izen-emate hori ez dago jada itxaron-zerrendan.',
	'Escribe el asunto y el mensaje.' => 'Idatzi gaia eta mezua.',
	'Ese email no es el de esta inscripción.' => 'Email hori ez da izen-emate honetakoa.',
	'Estado cambiado.' => 'Egoera aldatu da.',
	'Inscripción borrada de la lista de espera.' => 'Izen-ematea itxaron-zerrendatik ezabatu da.',
	'Las altas en el CRM no están activadas para tu grupo (wp-admin → Grupos Scouts → Módulos).' => 'CRMko altak ez daude aktibatuta zure talderako (wp-admin → Grupos Scouts → Módulos).',
	'Lista de espera del %s' => '%s(r)en itxaron-zerrenda',
	'Marca la casilla para confirmar que quieres borrar tus datos.' => 'Markatu laukia zure datuak ezabatu nahi dituzula berresteko.',
	'No se ha podido apuntar el contacto.' => 'Ezin izan da kontaktua erregistratu.',
	'No se ha podido asignar la sección.' => 'Ezin izan da atala esleitu.',
	'No se ha podido cambiar el estado.' => 'Ezin izan da egoera aldatu.',
	'Sección asignada: %s.' => 'Esleitutako atala: %s.',
	'Sección: la de su edad.' => 'Atala: bere adinari dagokiona.',
	'Sus datos de la lista de espera se han borrado.' => 'Itxaron-zerrendako bere datuak ezabatu dira.',
	'Ver la inscripción' => 'Ikusi izen-ematea',
	'Viene de la lista de espera: los datos son los que escribió la familia. Revísalos y completa lo que falta (el género). Al terminar, la inscripción se borra de la lista.' => 'Itxaron-zerrendatik dator: datuak familiak idatzitakoak dira. Berrikusi eta osatu falta dena (generoa). Amaitzean, izen-ematea zerrendatik ezabatzen da.',

	// v0.32: lista de espera (orden)
	'Orden' => 'Ordena',
	'Orden de llegada en su sección' => 'Iritsiera-ordena bere atalean',

	// v0.33: la cuenta en la ficha del CRM
	'%1$s: %2$s' => '%1$s: %2$s',
	'El CRM no ha guardado la cuenta en la ficha. Inténtalo más tarde o avisa a la Tesorería del grupo.' => 'CRMak ez du kontua fitxan gorde. Saiatu berriro geroago edo abisatu taldeko Diruzaintzari.',
	'El CRM no responde: inténtalo más tarde.' => 'CRMak ez du erantzuten: saiatu berriro geroago.',
	'Familia %s: la cuenta de su ficha del CRM ya no es la autorizada.' => '%s familia: CRMko fitxako kontua ez da jada baimendutakoa.',
	'La cuenta de su ficha del CRM no es la autorizada (o no está): tiene que firmar la autorización de nuevo' => 'CRMko fitxako kontua ez da baimendutakoa (edo ez dago): baimena berriro sinatu behar du',
	'La cuenta se guarda en la ficha del CRM y el usuario del CRM de tu grupo no tiene permiso para editar fichas. Avisa a la Tesorería del grupo.' => 'Kontua CRMko fitxan gordetzen da eta zure taldeko CRMko erabiltzaileak ez du fitxak editatzeko baimenik. Abisatu taldeko Diruzaintzari.',
	'La ficha del CRM solo admite cuentas de hasta %d caracteres (las españolas tienen 24): usa una cuenta española.' => 'CRMko fitxak gehienez %d karaktereko kontuak onartzen ditu (espainiarrek 24 dituzte): erabili Espainiako kontu bat.',
	'No se encuentran en el CRM las fichas de la familia.' => 'Familiaren fitxak ez dira CRMan aurkitzen.',
	'No se ha podido leer la cuenta de las familias en el CRM: inténtalo más tarde.' => 'Ezin izan da familien kontua CRMan irakurri: saiatu berriro geroago.',
	'Autorización de cobro (SEPA)' => 'Kobrantza-baimena (SEPA)',
	'Cuenta (IBAN)' => 'Kontua (IBAN)',
	'Datos bancarios y domiciliación SEPA' => 'Banku-datuak eta SEPA helbideratzea',
	'Entidad' => 'Erakundea',
	'Los datos bancarios se guardan en la ficha del CRM de Scouts de España (en la de cada miembro de la familia). Para ponerlos o cambiarlos, la madre, el padre, el tutor/a o el propio asociado mayor de edad firma una autorización en «Mis pagos».' => 'Banku-datuak Scouts de Españako CRMko fitxan gordetzen dira (familiako kide bakoitzaren fitxan). Jartzeko edo aldatzeko, amak, aitak, tutoreak edo adinez nagusi den bazkideak berak baimen bat sinatzen du «Nire ordainketak» atalean.',
	'Sin autorización: la familia paga por transferencia.' => 'Baimenik gabe: familiak transferentziaz ordaintzen du.',
	'Sin datos bancarios en la ficha' => 'Fitxan banku-daturik gabe',
	'Vigente · %1$s · firmada el %2$s' => 'Indarrean · %1$s · sinatua: %2$s',
	'⚠️ La cuenta de esta ficha no es la autorizada: no se cobrará hasta que se firme una autorización nueva.' => '⚠️ Fitxa honetako kontua ez da baimendutakoa: ez da kobratuko baimen berri bat sinatu arte.',
	'Cuenta española (24 caracteres). Se guarda, con el titular y la entidad, en la ficha de cada miembro de la familia en el CRM de Scouts de España; la web solo guarda tu autorización.' => 'Espainiako kontua (24 karaktere). Titularrarekin eta erakundearekin batera gordetzen da, Scouts de Españako CRMko familiako kide bakoitzaren fitxan; webak zure baimena soilik gordetzen du.',
	'Entidad (banco, opcional)' => 'Erakundea (bankua, aukerakoa)',
	'Los datos de la cuenta se guardan en la ficha de cada miembro de la familia en el CRM de Scouts de España; aquí solo se enseña enmascarada.' => 'Kontuaren datuak Scouts de Españako CRMko familiako kide bakoitzaren fitxan gordetzen dira; hemen kontua maskaratuta soilik erakusten da.',
	'⚠️ La cuenta que figura en la ficha del CRM ya no es la que autorizaste: hasta que firmes una autorización nueva no se cobrará nada por domiciliación.' => '⚠️ CRMko fitxan agertzen den kontua ez da jada baimendu zenuena: baimen berri bat sinatzen duzun arte ez da ezer kobratuko helbideratzearen bidez.',
	'Autorizar el cobro o cambiar la cuenta en «Mis pagos»' => 'Kobrantza baimendu edo kontua aldatu «Nire ordainketak» atalean',
	'Cuentas pasadas a las fichas del CRM: %1$d. Autorizaciones anuladas de las que se ha borrado la cuenta: %2$d.' => 'CRMko fitxetara pasatako kontuak: %1$d. Ezeztatutako baimenak, kontua ezabatu zaienak: %2$d.',
	'Ver las domiciliaciones (Tesorería)' => 'Ikusi helbideratzeak (Diruzaintza)',
	'Hay autorizaciones firmadas antes de la versión 0.33 que guardan la cuenta en la web. Pásalas a las fichas del CRM: desde entonces la web ya no guarda ninguna cuenta.' => '0.33 bertsioa baino lehen sinatutako baimen batzuek kontua webean gordetzen dute. Pasatu itzazu CRMko fitxetara: ordutik webak ez du konturik gordetzen.',
	'La cuenta (IBAN, titular y entidad) se guarda en la ficha del CRM de Scouts de España de cada miembro de la familia; la web guarda la autorización (quién la firmó y cuándo, y la dirección), el IBAN enmascarado y una huella para comprobar, antes de cobrar, que la cuenta del CRM sigue siendo la autorizada. La autorización se conserva mientras esté vigente y 14 meses después de anularla, como pide la norma SEPA.' => 'Kontua (IBANa, titularra eta erakundea) Scouts de Españako CRMko familiako kide bakoitzaren fitxan gordetzen da; webak baimena gordetzen du (nork sinatu zuen eta noiz, eta helbidea), IBANa maskaratuta eta hatz-marka bat, kobratu aurretik CRMko kontua baimendutakoa dela egiaztatzeko. Baimena indarrean dagoen bitartean eta ezeztatu eta 14 hilabetera arte gordetzen da, SEPA arauak eskatzen duen bezala.',
	'Pasar las cuentas al CRM' => 'Kontuak CRMra pasatu',
	'Titular: %s' => 'Titularra: %s',
	'¿Pasar las cuentas de las autorizaciones a las fichas del CRM? Se escriben en la ficha de cada miembro de la familia y se borran de la web.' => 'Baimenen kontuak CRMko fitxetara pasatu nahi dituzu? Familiako kide bakoitzaren fitxan idazten dira eta webetik ezabatzen dira.',
	'⚠️ La cuenta de su ficha del CRM no es la autorizada (o no está): no se le cobrará hasta que firme de nuevo.' => '⚠️ CRMko fitxako kontua ez da baimendutakoa (edo ez dago): ez zaio kobratuko berriro sinatu arte.',

	// v0.34: «+» del tipo en el banco
	'No se ha podido crear el tipo. Vuelve a intentarlo.' => 'Ezin izan da mota sortu. Saiatu berriro.',
	'Crear un tipo nuevo' => 'Sortu mota berri bat',
	'Tipo nuevo' => 'Mota berria',
	'← Volver a «Marcar como revisado»' => '← Itzuli «Markatu berrikusita gisa» atalera',

	// v0.34: buscador de Familias y «Socio/a desde» en la ficha
	'%d año' => '%d urte',
	'%d día' => '%d egun',
	'%d días' => '%d egun',
	'%d mes' => '%d hilabete',
	'%d meses' => '%d hilabete',
	'(%1$s, %2$s y %3$s)' => '(%1$s, %2$s eta %3$s)',
	'Socio/a desde' => 'Bazkide noiztik',
	'%1$d de %2$d familias' => '%1$d / %2$d familia',
	'Ninguna familia coincide con «%s».' => 'Ez dago «%s» bilaketarekin bat datorren familiarik.',
	'Nº de familia, nombre o nº de socio' => 'Familia-zk., izena edo bazkide-zenbakia',

	// v0.35: eventos (de la nube)
	'Salidas, acampadas y otras actividades: equipo dirigente, presupuesto, inscripciones, «Mis eventos» y cobros.' => 'Irteerak, kanpaldiak eta beste jarduera batzuk: talde zuzendaria, aurrekontua, izen-emateak, «Nire ekitaldiak» eta kobrantzak.',
	'Confírmala en «Mis eventos» antes del %s. Si no, pasará a la siguiente persona de la lista.' => 'Berretsi «Nire ekitaldiak» atalean %s baino lehen. Bestela, zerrendako hurrengo pertsonari pasatuko zaio.',
	'El evento %s se ha cancelado.' => '%s ekitaldia bertan behera geratu da.',
	'El grupo ha publicado un evento nuevo: %s.' => 'Taldeak ekitaldi berri bat argitaratu du: %s.',
	'La inscripción de %1$s en %2$s está confirmada.' => '%1$s(r)en izen-ematea %2$s ekitaldian berretsita dago.',
	'La inscripción se hace en «Mis eventos», hasta el %s.' => 'Izena «Nire ekitaldiak» atalean ematen da, %s arte.',
	'Llegada: %s' => 'Iritsiera: %s',
	'Lugar: %s' => 'Lekua: %s',
	'Salida: %s' => 'Irteera: %s',
	'Se ha liberado una plaza en %1$s para %2$s, que estaba en la lista de espera.' => 'Plaza bat libratu da %1$s ekitaldian %2$s(r)entzat, itxaron-zerrendan zegoena.',
	'Si ya habías pagado, Tesorería se pondrá en contacto contigo para la devolución.' => 'Dagoeneko ordaindu bazenuen, Diruzaintza zurekin harremanetan jarriko da itzulketarako.',
	'Te recordamos que %1$s va a %2$s.' => 'Gogorarazten dizugu %1$s %2$s ekitaldira doala.',
	'Todavía falta:' => 'Oraindik falta da:',
	'firmar la autorización de participación (en «Mis eventos») o entregarla en papel;' => 'parte hartzeko baimena sinatzea («Nire ekitaldiak» atalean) edo paperean ematea;',
	'pagar %1$s (referencia %2$s).' => '%1$s ordaintzea (%2$s erreferentzia).',
	'¿Dudas? Habla con el equipo de la sección.' => 'Zalantzarik? Hitz egin atalaren taldearekin.',
	'%1$d confirmadas, %2$d pendientes, %3$d en la lista de espera y %4$d bajas.' => '%1$d berretsita, %2$d zain, %3$d itxaron-zerrendan eta %4$d baja.',
	'%1$d de %2$d plazas ocupadas' => '%1$d plaza beteta, %2$d(e)tik',
	'%1$d previstos de %2$d plazas' => '%1$d aurreikusita, %2$d plazatik',
	'%1$s (%2$s)' => '%1$s (%2$s)',
	'%1$s de %2$s' => '%1$s / %2$s',
	'%1$s · %2$d inscripciones · pendiente %3$s' => '%1$s · %2$d izen-emate · %3$s zain',
