	'Agenda' => 'Agenda',
	'Ahora mismo no hay ningún evento abierto para ti ni para tu familia. Cuando el grupo publique uno, te llegará un email.' => 'Une honetan ez dago ekitaldi irekirik zuretzat edo zure familiarentzat. Taldeak bat argitaratzen duenean, mezu elektroniko bat jasoko duzu.',
	'Ahora no se puede responder a esta convocatoria.' => 'Orain ezin zaio deialdi honi erantzun.',
	'Ajuste guardado: el importe de la inscripción ha cambiado.' => 'Doikuntza gordeta: izen-ematearen zenbatekoa aldatu da.',
	'Al coste de cada participante se le suma este margen: es el fondo de emergencia de la actividad. Es el valor con el que nace cada evento nuevo; en cada uno se puede cambiar hasta que Tesorería valida su presupuesto.' => 'Parte-hartzaile bakoitzaren kostuari marjina hau gehitzen zaio: jardueraren larrialdi-funtsa da. Ekitaldi berri bakoitza balio honekin sortzen da; bakoitzean alda daiteke Diruzaintzak aurrekontua balioztatu arte.',
	'Al día' => 'Egunean',
	'Al inscribir firmas la autorización: queda registrado quién la firma, cuándo y qué versión del texto.' => 'Izena ematean baimena sinatzen duzu: erregistratuta geratzen da nork sinatzen duen, noiz eta testuaren zein bertsio.',
	'Al menos la mitad de los monitores tiene que tener la titulación de tiempo libre: hay %1$d titulados de %2$d.' => 'Begiraleen erdiek gutxienez aisialdiko titulazioa izan behar dute: %2$d(e)tik %1$d titulatu daude.',
	'Aplicar el margen del fondo de emergencia' => 'Aplikatu larrialdi-funtsaren marjina',
