	'Cada tipo da los valores con los que nace un evento: si tiene coste y si se comunica a ASDE Baleares (las actividades de 2 o más noches con 10 o más menores).' => 'Mota bakoitzak ematen ditu ekitaldi bat sortzeko balioak: kostua duen eta ASDE Baleares-i jakinarazten zaion (2 gau edo gehiagoko eta 10 adingabe edo gehiagoko jarduerak).',
