	'Cerrado: solo inscribe el equipo del evento' => 'Itxita: ekitaldiaren taldeak bakarrik ematen du izena',
	'Certificado' => 'Ziurtagiria',
	'Como madre, padre o tutor/a legal, autorizo su participación en esta actividad del grupo scout, organizada bajo la responsabilidad de su equipo de scouters, y declaro que he leído la información de la actividad. Autorizo también que, en caso de urgencia y si no se me puede localizar, el equipo tome las decisiones médicas, quirúrgicas o de traslado que indique el personal sanitario.' => 'Ama, aita edo legezko tutore gisa, baimena ematen dut talde eskautaren jarduera honetan parte hartzeko, bere scouter-taldearen ardurapean antolatua, eta adierazten dut jardueraren informazioa irakurri dudala. Era berean, baimena ematen dut, larrialdiren bat gertatuz gero eta ni aurkitu ezin banaute, taldeak osasun-langileek adierazten dituzten erabaki mediko, kirurgiko edo lekualdatzekoak har ditzan.',
