	'El certificado de delitos sexuales de %s tendrá más de 12 meses cuando acabe el evento: hay que renovarlo.' => '%s(r)en sexu-delituen ziurtagiriak 12 hilabete baino gehiago izango ditu ekitaldia amaitzean: berritu egin behar da.',
	'El enlace al mapa tiene que ser una dirección web (https://…).' => 'Maparako estekak web helbide bat izan behar du (https://…).',
	'El equipo del grupo' => 'Taldeko ekipoa',
	'El evento %s vuelve a ser un borrador.' => '%s ekitaldia zirriborro bihurtu da berriro.',
	'El evento no puede acabar antes de empezar.' => 'Ekitaldia ezin da hasi baino lehen amaitu.',
	'El margen del fondo de emergencia tiene que estar entre 0 y 50 %.' => 'Larrialdi-funtsaren marjinak 0 eta 50 % artean egon behar du.',
	'El plazo de inscripción no puede acabar antes de empezar.' => 'Izena emateko epea ezin da hasi baino lehen amaitu.',
	'El plazo de inscripción tiene que acabar antes de que empiece el evento.' => 'Izena emateko epeak ekitaldia hasi baino lehen amaitu behar du.',
	'El plazo de inscripción ya se ha cerrado: para la baja, habla con el equipo del evento.' => 'Izena emateko epea itxita dago: baja emateko, hitz egin ekitaldiaren taldearekin.',
	'El precio se calcula con los participantes previstos y, una vez validado, ya no cambia: lo que sobre o falte lo asume el grupo.' => 'Prezioa aurreikusitako parte-hartzaileekin kalkulatzen da eta, behin balioztatuta, ez da aldatzen: soberan edo falta dena taldeak hartzen du bere gain.',
	'El presupuesto de este evento no se puede cambiar.' => 'Ekitaldi honen aurrekontua ezin da aldatu.',
	'El presupuesto está validado: las secciones y los participantes previstos no se pueden cambiar (Tesorería puede reabrirlo).' => 'Aurrekontua balioztatuta dago: atalak eta aurreikusitako parte-hartzaileak ezin dira aldatu (Diruzaintzak berriro ireki dezake).',
	'El presupuesto ya está validado y el precio es fijo: para cambiar las secciones, los participantes previstos o si tiene coste, pide a Tesorería que reabra el presupuesto.' => 'Aurrekontua balioztatuta dago eta prezioa finkoa da: atalak, aurreikusitako parte-hartzaileak edo kostua duen aldatzeko, eskatu Diruzaintzari aurrekontua berriro irekitzeko.',
	'Elige a un scouter o voluntario/a del grupo.' => 'Aukeratu taldeko scouter edo boluntario bat.',
	'Elige a una persona del grupo.' => 'Aukeratu taldeko pertsona bat.',
