	'En la ficha de %s consta el certificado de delitos sexuales, pero sin fecha: no se puede saber si tiene menos de 12 meses.' => '%s(r)en fitxan sexu-delituen ziurtagiria ageri da, baina datarik gabe: ezin da jakin 12 hilabete baino gutxiago duen.',
	'En la ficha de %s no consta el certificado de delitos sexuales.' => '%s(r)en fitxan ez da ageri sexu-delituen ziurtagiria.',
	'En lista de espera' => 'Itxaron-zerrendan',
	'En nombre de su familia: si es menor, la autorización llega en papel y la marcas aquí cuando la tengas.' => 'Bere familiaren izenean: adingabea bada, baimena paperean iristen da eta hemen markatzen duzu jasotzen duzunean.',
	'En prácticas' => 'Praktiketan',
	'En total: %1$d de %2$d' => 'Guztira: %1$d / %2$d',
	'En un evento de grupo sin secciones marcadas se convoca a todas las secciones educativas.' => 'Atalik markatu gabeko taldeko ekitaldi batean, hezkuntza-atal guztiei deitzen zaie.',
	'Enlace al mapa (opcional)' => 'Maparako esteka (aukerakoa)',
	'Entregada en papel' => 'Paperean emana',
	'Enviado a Tesorería el %s: falta que lo valide.' => 'Diruzaintzara bidalia (%s): balioztatzea falta da.',
