	'Equipo dirigente: director/a titulado, ratio cubierta y certificados al día.' => 'Talde zuzendaria: zuzendari titulatua, ratioa beteta eta ziurtagiriak egunean.',
	'Es lo que firma la familia al inscribir a un menor (encima sale a quién y a qué evento autoriza). Versión actual: %s. Si lo cambias, las firmas anteriores siguen guardando la versión que firmaron. Déjalo vacío para usar el del plugin.' => 'Familiak adingabe baten izena ematean sinatzen duena da (gainean ateratzen da nori eta zein ekitalditarako ematen duen baimena). Uneko bertsioa: %s. Aldatzen baduzu, aurreko sinadurek sinatu zuten bertsioa gordetzen jarraituko dute. Utzi hutsik pluginarena erabiltzeko.',
	'Es más de lo que queda por pagar (%s).' => 'Ordaintzeko geratzen dena baino gehiago da (%s).',
	'Es una preinscripción: tu familia tendrá que firmar la autorización desde su cuenta (o entregarla en papel).' => 'Aurre-izen-ematea da: zure familiak bere kontutik sinatu beharko du baimena (edo paperean eman).',
	'Esa familia no tiene nada pendiente en este evento.' => 'Familia horrek ez du ezer zain ekitaldi honetan.',
	'Esa plaza ya no está disponible.' => 'Plaza hori ez dago eskuragarri.',
	'Esa sección no está convocada.' => 'Atal horri ez zaio deitu.',
	'Escribe el concepto y un importe mayor que cero.' => 'Idatzi kontzeptua eta zero baino handiagoa den zenbatekoa.',
