	'Escribe el nombre del evento.' => 'Idatzi ekitaldiaren izena.',
	'Escribe los gastos previstos y cómo se reparte cada uno. El precio de cada sección sale del coste (el del equipo, repartido entre los participantes) más el margen del fondo de emergencia, redondeado al euro. Cuando esté listo, envíalo a Tesorería para que lo valide.' => 'Idatzi aurreikusitako gastuak eta bakoitza nola banatzen den. Atal bakoitzaren prezioa kostutik ateratzen da (taldearena, parte-hartzaileen artean banatuta) gehi larrialdi-funtsaren marjina, eurora biribilduta. Prest dagoenean, bidali Diruzaintzara balioztatzeko.',
	'Escribe un importe mayor que cero.' => 'Idatzi zero baino handiagoa den zenbateko bat.',
	'Ese movimiento no se puede anular.' => 'Mugimendu hori ezin da ezeztatu.',
	'Esta autorización no se puede firmar.' => 'Baimen hau ezin da sinatu.',
