	'Este evento no es para su sección o su edad.' => 'Ekitaldi hau ez da bere atalarentzat edo adinarentzat.',
	'Este evento no tiene coste para las familias. Si lo tiene, márcalo en «Editar los datos» y prepara aquí el presupuesto.' => 'Ekitaldi honek ez du kosturik familientzat. Baldin badu, markatu «Editatu datuak» atalean eta prestatu hemen aurrekontua.',
	'Este evento tiene coste: antes de publicarlo, Tesorería tiene que validar su presupuesto.' => 'Ekitaldi honek kostua du: argitaratu aurretik, Diruzaintzak aurrekontua balioztatu behar du.',
	'Este evento ya no se puede volver a borrador.' => 'Ekitaldi hau ezin da jada zirriborrora itzuli.',
	'Este presupuesto no se puede enviar a Tesorería.' => 'Aurrekontu hau ezin da Diruzaintzara bidali.',
	'Este presupuesto ya no se puede reabrir.' => 'Aurrekontu hau ezin da jada berriro ireki.',
	'Esto solo lo ve el equipo del evento y se borra al cerrarlo. La salud y la alimentación no se escriben aquí: van en la ficha.' => 'Hau ekitaldiaren taldeak bakarrik ikusten du eta ekitaldia ixtean ezabatzen da. Osasuna eta elikadura ez dira hemen idazten: fitxan doaz.',
