	'pagar <strong>%1$s</strong>, con la referencia <strong>%2$s</strong> si es por transferencia o Bizum.' => '<strong>%1$s</strong> ordaintzea, <strong>%2$s</strong> erreferentziarekin transferentzia edo Bizum bidez bada.',
	'por persona' => 'pertsonako',
	'que tu familia firme la autorización de participación desde su cuenta (o la entregue en papel al equipo).' => 'zure familiak parte hartzeko baimena bere kontutik sinatzea (edo paperean ematea taldeari).',
	'«Por persona: participantes y equipo» es lo que cuesta cada persona (albergue, comida): lo del equipo se reparte entre los participantes. «Solo el equipo» es lo que cuesta un scouter (p. ej. su plaza en un evento externo).' => '«Pertsonako: parte-hartzaileak eta taldea» pertsona bakoitzak balio duena da (aterpetxea, janaria): taldearena parte-hartzaileen artean banatzen da. «Taldea soilik» scouter batek balio duena da (adib. bere plaza kanpoko ekitaldi batean).',
	'¿Anular este movimiento? Si es un pago de la familia, se anula entero.' => 'Mugimendu hau ezeztatu? Familiaren ordainketa bat bada, osorik ezeztatzen da.',
	'¿Borrar este borrador con su equipo y su presupuesto? No se puede deshacer.' => 'Zirriborro hau bere taldearekin eta aurrekontuarekin ezabatu? Ezin da desegin.',
	'¿Cancelar el evento? No se puede deshacer.' => 'Ekitaldia bertan behera utzi? Ezin da desegin.',
	'¿Dar de baja esta inscripción? Lo que ya se haya pagado lo revisará Tesorería.' => 'Izen-emate honi baja eman? Dagoeneko ordaindutakoa Diruzaintzak berrikusiko du.',
	'¿Publicar el evento? Lo verán los scouters de las secciones convocadas.' => 'Ekitaldia argitaratu? Deitutako ataletako scouterrek ikusiko dute.',
	'¿Quitar a esta persona del equipo?' => 'Pertsona hau taldetik kendu?',
	'¿Reabrir el presupuesto? Habrá que volver a validarlo antes de publicar.' => 'Aurrekontua berriro ireki? Argitaratu aurretik berriro balioztatu beharko da.',
	'¿Validar el presupuesto? El precio por sección quedará fijo.' => 'Aurrekontua balioztatu? Atal bakoitzeko prezioa finko geratuko da.',
	'¿Volver a dejar el evento como borrador?' => 'Ekitaldia zirriborro gisa utzi berriro?',
