	// v0.35.1: familias, eliminar de la web
	'Eliminar de la web' => 'Ezabatu webetik',
	'No tiene membresía activa: deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada; si vuelve a tener una membresía activa, vuelve a salir.' => 'Ez du kidetza aktiborik: Pertsonak atalean ez da gehiago agertuko, bere familiatik aterako da eta bere sarbide-kontuak desaktibatuko dira. CRMan ez da ezer aldatzen; berriro kidetza aktiboa badu, berriro agertuko da.',
	'¿Eliminar a %s de la web? Deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada.' => '%s webetik ezabatu? Pertsonak atalean ez da gehiago agertuko, bere familiatik aterako da eta bere sarbide-kontuak desaktibatuko dira. CRMan ez da ezer aldatzen.',
	'No hay ningún grupo elegido.' => 'Ez dago talderik aukeratuta.',
	'Solo se puede eliminar de la web a quien no tiene ninguna membresía activa. Antes, dale de baja.' => 'Kidetza aktiborik ez duena bakarrik ezaba daiteke webetik. Lehenago, eman baja.',
	'%s ya no sale en la web. En el CRM no ha cambiado nada.' => '%s ez da gehiago agertzen webean. CRMan ez da ezer aldatu.',
	'Familia eliminada.' => 'Familia ezabatu da.',
	'Ha salido de la familia nº %s.' => '%s zenbakiko familiatik atera da.',
	'Su cuenta de acceso se ha desactivado.' => 'Bere sarbide-kontua desaktibatu da.',
	'Ya no está en %1$d cuenta(s) familiar(es); %2$d se han desactivado porque no representan a nadie más.' => 'Ez dago gehiago %1$d familia-kontutan; %2$d desaktibatu dira, beste inor ordezkatzen ez dutelako.',
	'Eliminar' => 'Ezabatu',
	'Eliminar esta familia' => 'Ezabatu familia hau',
	'Solo se puede eliminar una familia sin socios.' => 'Bazkiderik gabeko familia bakarrik ezaba daiteke.',
	'Tiene autorizaciones de domiciliación: no se puede eliminar.' => 'Helbideratze-baimenak ditu: ezin da ezabatu.',
