	// v0.36.1: reabrir las cuentas
	'Al cerrar, el balance de hoy queda como informe final, se borran los datos de recogida y las observaciones de las inscripciones y el evento queda en solo lectura. Si después hace falta cambiar algo, Tesorería puede reabrirlas (lo borrado no vuelve).' => 'Ixtean, gaurko balantzea azken txosten gisa geratzen da, izen-emateetako jasotze-datuak eta oharrak ezabatzen dira eta ekitaldia irakurtzeko soilik geratzen da. Gero zerbait aldatu behar bada, Diruzaintzak berriro ireki ditzake (ezabatutakoa ez da itzultzen).',
	'Cuentas cerradas el %1$s por %2$s: este es el informe final. Para cambiar algo, Tesorería tiene que reabrirlas.' => 'Kontuak %1$s(e)an itxi zituen %2$s(e)k: hau da azken txostena. Zerbait aldatzeko, Diruzaintzak berriro ireki behar ditu.',
	'Cuentas del evento %s reabiertas: ya se pueden cambiar. Cuando esté todo, ciérralas de nuevo.' => '%s ekitaldiaren kontuak berriro irekita: aldatu daitezke jada. Dena prest dagoenean, itxi berriro.',
	'Escribe el motivo para reabrir las cuentas.' => 'Idatzi kontuak berriro irekitzeko arrazoia.',
	'Las cuentas de este evento no están cerradas.' => 'Ekitaldi honen kontuak ez daude itxita.',
	'Las cuentas las reabre Tesorería.' => 'Kontuak Diruzaintzak irekitzen ditu berriro.',
	'No se han podido reabrir las cuentas. Inténtalo de nuevo.' => 'Ezin izan dira kontuak berriro ireki. Saiatu berriro.',
	'Reabrir las cuentas' => 'Ireki berriro kontuak',
	'Se podrá volver a cambiar el evento y sus cuentas. Quién recoge y las observaciones, que se borraron al cerrar, no vuelven.' => 'Ekitaldia eta haren kontuak berriro aldatu ahal izango dira. Nork jasotzen duen eta oharrak, ixtean ezabatu zirenak, ez dira itzultzen.',
	'¿Cerrar las cuentas del evento? Quién recoge y las observaciones de las inscripciones se borran y no vuelven.' => 'Ekitaldiaren kontuak itxi nahi dituzu? Izen-emateetan nork jasotzen duen eta oharrak ezabatu egiten dira eta ez dira itzultzen.',
	'¿Reabrir las cuentas del evento? Habrá que volver a cerrarlas.' => 'Ekitaldiaren kontuak berriro ireki nahi dituzu? Berriro itxi beharko dira.',

	// v0.37: pagos de eventos en Registrar pago, historial de pagos, informes en Tesorería, Excel
	'%d familia' => '%d familia',
	'%d familias' => '%d familia',
	'El ingreso del banco solo se asocia a la cuota de la ronda. Para un evento, quita el ingreso y escribe el pago.' => 'Banku-sarrera txandako kuotari soilik lotzen zaio. Ekitaldi baterako, kendu sarrera eta idatzi ordainketa.',
	'Ese evento no está abierto a inscripciones o esta familia no tiene nada pendiente en él.' => 'Ekitaldi hori ez dago izen-emateetarako irekita edo familia honek ez du ezer zain hartan.',
	'Informe de pagos' => 'Ordainketen txostena',
	'Pago de %1$s registrado en el evento «%2$s». Queda en el historial de pagos de la familia.' => '%1$s(r)en ordainketa erregistratu da «%2$s» ekitaldian. Familiaren ordainketa-historian geratzen da.',
	'Para un evento, la forma de pago es efectivo, transferencia o Bizum.' => 'Ekitaldi baterako, ordainketa-modua eskudirua, transferentzia edo Bizum da.',
	'Ronda %1$s · generado el %2$s' => 'Txanda: %1$s · sortua: %2$s',
	'Todos los informes' => 'Txosten guztiak',
	'Beca o ajuste de %1$s · evento «%2$s»' => '%1$s(e)ko beka edo doikuntza · «%2$s» ekitaldia',
	'Devolución de %1$s · evento «%2$s»' => '%1$s(e)ko itzulketa · «%2$s» ekitaldia',
	'Evento «%1$s» (pendiente %2$s)' => '«%1$s» ekitaldia (zain: %2$s)',
	'Historial de pagos' => 'Ordainketen historia',
	'La cuota de la ronda %s' => '%s txandako kuota',
	'Pago de' => 'Ordainketaren xedea',
	'Pago de %1$s · evento «%2$s»' => '%1$s(e)ko ordainketa · «%2$s» ekitaldia',
	'Pago de %1$s · pedido de uniforme %2$s' => '%1$s(e)ko ordainketa · uniforme-eskaera %2$s',
	'Solo salen los eventos con la inscripción abierta en los que esta familia tiene algo pendiente. Para un evento: efectivo, transferencia o Bizum, y sin ingreso del banco.' => 'Izen-ematea irekita duten eta familia honek zerbait zain duen ekitaldiak soilik agertzen dira. Ekitaldi baterako: eskudirua, transferentzia edo Bizum, eta banku-sarrerarik gabe.',
	'Todo lo que ha pagado esta familia: la cuota de la ronda, los eventos y los uniformes, con quién lo registró y cuándo. Lo eliminado no cuenta.' => 'Familia honek ordaindu duen guztia: txandako kuota, ekitaldiak eta uniformeak, nork eta noiz erregistratu zuen. Ezabatutakoak ez du balio.',
	'anulado' => 'baliogabetua',
	'evento' => 'ekitaldia',
	'uniforme' => 'uniformea',

	// v0.38: campos propios de la lista de espera
	'Casilla (sí / no)' => 'Laukia (bai / ez)',
	'Número' => 'Zenbakia',
	'Texto corto' => 'Testu laburra',
	'Texto largo' => 'Testu luzea',
	'(opcional)' => '(aukerakoa)',
	'Además de los datos que siempre se piden, tu grupo puede añadir preguntas al formulario de la lista de espera. Cada campo necesita su etiqueta (el texto que verá quien se apunta) y se elige su tipo y si es obligatorio. Las respuestas se guardan cifradas con la clave del email de quien se apunta y se borran con la inscripción. Quitar o cambiar un campo no altera lo que ya contestaron.' => 'Beti eskatzen diren datuez gain, zure taldeak galderak gehi ditzake itxaron-zerrendako inprimakian. Eremu bakoitzak bere etiketa behar du (izena ematen duenak ikusiko duen testua), eta mota eta derrigorrezkoa den ala ez aukeratzen dira. Erantzunak zifratuta gordetzen dira izena ematen duenaren emailaren gakoarekin, eta izen-emateak ezabatzean ezabatzen dira. Eremu bat kentzeak edo aldatzeak ez du lehendik erantzundakoa aldatzen.',
	'Cada campo necesita su etiqueta: es el texto que verá quien se apunta.' => 'Eremu bakoitzak bere etiketa behar du: izena ematen duenak ikusiko duen testua da.',
	'Campos propios del formulario' => 'Inprimakiaren eremu propioak',
	'Como máximo, %d campos propios.' => 'Gehienez, %d eremu propio.',
	'Elige el tipo de cada campo.' => 'Aukeratu eremu bakoitzaren mota.',
	'Etiqueta' => 'Etiketa',
	'Falta rellenar «%s».' => 'Falta da «%s» betetzea.',
	'Guardar los campos' => 'Gorde eremuak',
	'Las filas vacías se ignoran. Para añadir más campos, guarda y vuelve a abrir este cuadro. Máximo %d campos.' => 'Errenkada hutsak ez dira kontuan hartzen. Eremu gehiago gehitzeko, gorde eta ireki berriro koadro hau. Gehienez %d eremu.',
	'Más datos que pide el grupo' => 'Taldeak eskatzen dituen datu gehiago',
	'Obligatorio' => 'Derrigorrezkoa',
	'Opcional' => 'Aukerakoa',
	'«%s» no es una fecha válida.' => '«%s» ez da baliozko data.',
	'«%s» tiene que ser un número.' => '«%s» zenbaki bat izan behar da.',
	'Campos del formulario guardados.' => 'Inprimakiaren eremuak gorde dira.',

	// v0.39: avisos de eventos configurables
	'Al final' => 'Amaieran',
	'Al principio' => 'Hasieran',
	'Avisar también en la app móvil (si la usa el grupo)' => 'Mugikorreko aplikazioan ere abisatu (taldeak erabiltzen badu)',
	'Avisos' => 'Abisuak',
	'Días para confirmar una plaza ofrecida de la lista de espera' => 'Itxaron-zerrendako plaza bat berresteko egunak',
	'Edad desde la que una persona recibe los avisos en su propia cuenta y se inscribe sola' => 'Pertsona batek abisuak bere kontuan jasotzen dituen eta bere kabuz izena ematen duen adina',
	'Evento cancelado' => 'Ekitaldia bertan behera utzi da',
	'Evento nuevo: al publicarlo, a las personas convocadas' => 'Ekitaldi berria: argitaratzean, deituriko pertsonei',
	'Inscripción confirmada' => 'Izen-ematea berretsita',
	'Plaza liberada para quien está en la lista de espera' => 'Itxaron-zerrendan dagoenarentzat plaza libre',
	'Qué avisos manda el área privada a las familias y a las personas inscritas. Cada grupo decide los suyos.' => 'Eremu pribatuak familiei eta izena emandako pertsonei zer abisu bidaltzen dizkien. Talde bakoitzak berea erabakitzen du.',
	'Recordatorio antes del evento (con los días de arriba)' => 'Ekitaldiaren aurreko gogorarazpena (goiko egunekin)',
	'Segundo recordatorio (días antes del evento; 0 = no se manda; menos que el primero)' => 'Bigarren gogorarazpena (ekitaldiaren aurreko egunak; 0 = ez da bidaltzen; lehenengoa baino gutxiago)',
	'Si desactivas el aviso de plaza liberada, la plaza se sigue ofreciendo, pero la familia no recibe el email: tendrá que mirarlo en la aplicación.' => 'Plaza libre egotearen abisua desaktibatzen baduzu, plaza eskaintzen jarraitzen da, baina familiak ez du emailik jasoko: aplikazioan begiratu beharko du.',
	'Textos propios de los avisos' => 'Abisuen testu propioak',
	'Un párrafo opcional al principio y otro al final de cada email (hasta %d caracteres). Salen igual en todos los idiomas: escríbelos en el idioma de tus familias.' => 'Aukerako paragrafo bat hasieran eta beste bat amaieran, email bakoitzean (%d karaktere arte). Hizkuntza guztietan berdin ateratzen dira: idatzi itzazu zure familien hizkuntzan.',
);
